def cryptoCategories(start=None, limit=None, id=None, slug=None, symbol=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str) or not x:
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date().isoformat()

    def _month_bucket(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # ---- Validate params (schema: numbers for paging; strings for filters)
    if start is not None and not isinstance(start, (int, float)):
        return _err("VALIDATION_ERROR", "start must be a number")
    if limit is not None and not isinstance(limit, (int, float)):
        return _err("VALIDATION_ERROR", "limit must be a number")
    if id is not None and not isinstance(id, str):
        return _err("VALIDATION_ERROR", "id must be a string")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string")
    if symbol is not None and not isinstance(symbol, str):
        return _err("VALIDATION_ERROR", "symbol must be a string")

    start_i = None
    limit_i = None
    if start is not None:
        if int(start) != start or start < 1:
            return _err("VALIDATION_ERROR", "start must be an integer >= 1")
        start_i = int(start)
    if limit is not None:
        if int(limit) != limit or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        limit_i = int(limit)

    # Mutually invalid filters: per business rules, categories filter by upstream_id OR slug
    # If both provided, require they refer to same row; otherwise validation error.
    if id is not None and slug is not None:
        if not id.strip() or not slug.strip():
            return _err("VALIDATION_ERROR", "id and slug must be non-empty when provided together")

    # ---- Ambient auth: find any active api key that can serve the call and enforce its quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    def _select_key():
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            # Must have required fields
            if not k.get("id"):
                continue
            return k
        return None

    key = _select_key()
    if not key:
        # still must log exactly one request row; but fk requires api_key_id, so we can only log if a key exists
        return _err("UNAUTHORIZED", "No active API key available")

    # ---- Rate/Quota bookkeeping (minute/day/month boundaries)
    last = _parse_dt(key.get("last_request_at"))
    last_min = _minute_bucket(last) if last else None
    now_min = _minute_bucket(now)
    if last_min is None or now_min != last_min:
        key["requests_this_minute"] = 0

    last_day = _day_bucket(last) if last else None
    now_day = _day_bucket(now)
    if last_day is None or now_day != last_day:
        key["requests_today"] = 0

    last_month = _month_bucket(last) if last else None
    now_month = _month_bucket(now)
    if last_month is None or now_month != last_month:
        key["credits_month_to_date"] = 0

    rpm_lim = key.get("requests_per_minute_limit", 0)
    rpd_lim = key.get("requests_per_day_limit", 0)
    mcred_lim = key.get("monthly_credit_limit", 0)

    if not isinstance(rpm_lim, int) or rpm_lim < 0:
        rpm_lim = 0
    if not isinstance(rpd_lim, int) or rpd_lim < 0:
        rpd_lim = 0
    if not isinstance(mcred_lim, int) or mcred_lim < 0:
        mcred_lim = 0

    if rpm_lim > 0 and int(key.get("requests_this_minute", 0)) >= rpm_lim:
        # log and return RATE_LIMIT
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": "cryptoCategories",
            "request_params": {k: v for k, v in {"start": start, "limit": limit, "id": id, "slug": slug, "symbol": symbol}.items() if v is not None},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limit",
            "error_message": "requests_per_minute_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")

    if rpd_lim > 0 and int(key.get("requests_today", 0)) >= rpd_lim:
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": "cryptoCategories",
            "request_params": {k: v for k, v in {"start": start, "limit": limit, "id": id, "slug": slug, "symbol": symbol}.items() if v is not None},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limit",
            "error_message": "requests_per_day_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-day)")

    # credits for this tool (directory read): charge 1
    credits_charged = 1
    if mcred_lim > 0 and int(key.get("credits_month_to_date", 0)) + credits_charged > mcred_lim:
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": "cryptoCategories",
            "request_params": {k: v for k, v in {"start": start, "limit": limit, "id": id, "slug": slug, "symbol": symbol}.items() if v is not None},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly credit limit exceeded")

    # ---- Read categories
    cats = _load("categories_and_memberships.json")
    if not isinstance(cats, list):
        cats = []

    # Optional "symbol" filter: categories don't have symbol; interpret as filter categories containing a crypto with that symbol.
    # If symbol provided, resolve to crypto asset(s) and filter memberships.
    crypto_symbol_ids = None
    if symbol is not None:
        sym = symbol.strip()
        if not sym:
            return _err("VALIDATION_ERROR", "symbol must be non-empty when provided")
        assets = _load("asset_directory.json")
        if not isinstance(assets, list):
            assets = []
        crypto_symbol_ids = set()
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("entity_type") != "cryptocurrency":
                continue
            if (a.get("symbol") or "").upper() == sym.upper():
                crypto_symbol_ids.add(a.get("upstream_id"))
        # If no crypto matches symbol, categories result is empty (not error)

    # Filter categories
    filtered = []
    for c in cats:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "deleted":
            continue
        if id is not None:
            if str(c.get("upstream_id")) != id:
                continue
        if slug is not None:
            if (c.get("slug") or "") != slug:
                continue
        if crypto_symbol_ids is not None:
            memberships = c.get("memberships")
            if not isinstance(memberships, list):
                continue
            ok = False
            for m in memberships:
                if isinstance(m, dict) and str(m.get("upstream_crypto_id")) in crypto_symbol_ids:
                    ok = True
                    break
            if not ok:
                continue
        filtered.append(c)

    # Validate id+slug mutual condition if both provided
    if id is not None and slug is not None:
        # if provided but no row matches, treat as empty set (read tool returns empty)
        # however if there exists a row for id but slug differs, it's a validation error ("mutually invalid filters")
        by_id = None
        for c in cats:
            if isinstance(c, dict) and str(c.get("upstream_id")) == id and c.get("status") != "deleted":
                by_id = c
                break
        if by_id is not None and (by_id.get("slug") or "") != slug:
            return _err("VALIDATION_ERROR", "id and slug refer to different categories")

    # Deterministic order: upstream_id asc (string compare)
    filtered.sort(key=lambda x: (str(x.get("upstream_id") or ""), str(x.get("id") or "")))

    total = len(filtered)
    s = start_i if start_i is not None else 1
    l = limit_i if limit_i is not None else 100
    # clamp large limits (service-like guard)
    if l > 5000:
        return _err("VALIDATION_ERROR", "limit too large")
    offset = s - 1
    page = filtered[offset: offset + l]
    has_more = offset + l < total

    # Response projection: mimic CMC category list subset
    data = []
    for c in page:
        data.append({
            "id": str(c.get("upstream_id")),
            "name": c.get("name"),
            "title": c.get("name"),
            "slug": c.get("slug"),
            "num_tokens": c.get("num_tokens"),
            "description": c.get("description"),
        })

    # ---- Persist usage and request log
    key["requests_this_minute"] = int(key.get("requests_this_minute", 0)) + 1
    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0)) + credits_charged
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    rid = _gen_id("req")
    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": rid,
        "api_key_id": key["id"],
        "tool_name": "cryptoCategories",
        "request_params": {k: v for k, v in {"start": start_i if start_i is not None else None, "limit": limit_i if limit_i is not None else None, "id": id, "slug": slug, "symbol": symbol}.items() if v is not None},
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": credits_charged,
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)

    return {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None, "elapsed": duration_ms, "credit_count": credits_charged},
        "data": data,
        "metadata": {"start": s, "limit": l, "total_count": total, "has_more": has_more}
    }

def cryptoCategory(id, start=None, limit=None, convert=None, convert_id=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "cryptoCategory"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _coerce_int(v, name):
        if v is None:
            return None
        if isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number")
        if isinstance(v, (int, float)):
            if isinstance(v, float) and (v != v):
                return _err("VALIDATION_ERROR", f"{name} must be a number")
            iv = int(v)
            if abs(v - iv) > 1e-9:
                return _err("VALIDATION_ERROR", f"{name} must be an integer")
            return iv
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return _err("VALIDATION_ERROR", f"{name} must be a non-empty stringified integer")
            try:
                return int(s)
            except ValueError:
                return _err("VALIDATION_ERROR", f"{name} must be an integer")
        return _err("VALIDATION_ERROR", f"{name} must be a number")

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")

        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0

        if not isinstance(rpm, int):
            try:
                rpm = int(rpm)
            except Exception:
                rpm = 0
        if not isinstance(rpd, int):
            try:
                rpd = int(rpd)
            except Exception:
                rpd = 0
        if not isinstance(mcl, int):
            try:
                mcl = int(mcl)
            except Exception:
                mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    # Validate request params schema (additionalProperties=false already enforced by tool signature)
    request_params = {}
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    request_params["id"] = id

    si = _coerce_int(start, "start")
    if isinstance(si, dict) and "error" in si:
        return si
    li = _coerce_int(limit, "limit")
    if isinstance(li, dict) and "error" in li:
        return li

    if si is not None:
        if si < 1:
            return _err("VALIDATION_ERROR", "start must be >= 1 (1-based pagination)")
        request_params["start"] = si
    if li is not None:
        if li < 1 or li > 5000:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 5000")
        request_params["limit"] = li

    if convert is not None:
        if not isinstance(convert, str) or not convert.strip():
            return _err("VALIDATION_ERROR", "convert must be a non-empty string when provided")
        request_params["convert"] = convert.strip().upper()
    if convert_id is not None:
        if not isinstance(convert_id, str) or not convert_id.strip():
            # schema says string; accept numeric-ish as string too
            if isinstance(convert_id, (int, float)) and not isinstance(convert_id, bool):
                convert_id = str(int(convert_id))
            else:
                return _err("VALIDATION_ERROR", "convert_id must be a non-empty string when provided")
        request_params["convert_id"] = str(convert_id).strip()

    # Auth context (ambient): pick any active API key
    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    cache_key = None
    cache_hit = False
    credits = 1

    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    # Serve from cached_responses if present/valid (optional, but consistent with service model)
    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        # enforce quota then log
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        cache_hit = True
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((time.time() - t0) * 1000))
                        return c["response_body"]
                break

    # Resolve category by upstream_id (tool param id refers to category upstream_id)
    cats = _load("categories_and_memberships.json")
    if not isinstance(cats, list):
        cats = []
    cat = None
    for r in cats:
        if isinstance(r, dict) and r.get("status") != "deleted" and r.get("upstream_id") == id:
            cat = r
            break
    if cat is None:
        # still allow deleted? real would probably 404; do 404 regardless
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message=f"Category not found: {id}")
        return _err("NOT_FOUND", f"Category not found: {id}")

    memberships = cat.get("memberships", [])
    if not isinstance(memberships, list):
        memberships = []

    # deterministic membership order: upstream_crypto_id asc (string), then added_at asc
    def _mkey(m):
        if not isinstance(m, dict):
            return ("", "")
        return (str(m.get("upstream_crypto_id") or ""), str(m.get("added_at") or ""))
    memberships_sorted = sorted(memberships, key=_mkey)

    total_members = len(memberships_sorted)

    if si is None:
        si = 1
    if li is None:
        li = 100  # reasonable default; tool says includes when provided, but returning some is fine
    start_idx = si - 1
    page = memberships_sorted[start_idx:start_idx + li]

    # Resolve member assets and attach latest pricing (when available)
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    asset_by_upstream_crypto_id = {}
    for a in assets:
        if isinstance(a, dict) and a.get("entity_type") == "cryptocurrency":
            asset_by_upstream_crypto_id[str(a.get("upstream_id"))] = a

    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    # Build index of latest quote per asset_id + convert selector
    conv_sym = request_params.get("convert")
    conv_id = request_params.get("convert_id")

    def _match_convert(row):
        if conv_sym is None and conv_id is None:
            return (row.get("convert_symbol") in (None, "",)) and (row.get("convert_upstream_id") in (None, "",))
        ok = True
        if conv_sym is not None:
            ok = ok and (str(row.get("convert_symbol") or "").upper() == conv_sym.upper())
        if conv_id is not None:
            ok = ok and (str(row.get("convert_upstream_id") or "") == str(conv_id))
        return ok

    latest_quote = {}
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "crypto_quote_latest":
            continue
        if r.get("status") in ("deleted",):
            continue
        if not _match_convert(r):
            continue
        aid = r.get("primary_asset_id")
        if not aid:
            continue
        as_of = _parse_iso(r.get("as_of"))
        if as_of is None:
            continue
        prev = latest_quote.get(aid)
        if prev is None or (_parse_iso(prev.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < as_of:
            latest_quote[aid] = r

    members_out = []
    for mem in page:
        if not isinstance(mem, dict):
            continue
        ucid = str(mem.get("upstream_crypto_id") or "")
        a = asset_by_upstream_crypto_id.get(ucid)
        if not a:
            continue
        q = latest_quote.get(a.get("id"))
        quote_payload = None
        if isinstance(q, dict):
            quote_payload = {
                "as_of": q.get("as_of"),
                "convert": conv_sym,
                "convert_id": conv_id,
                "numeric": q.get("numeric_fields", {}),
                "aux": q.get("aux_fields", {}),
            }
        members_out.append({
            "crypto_asset": {
                "id": a.get("id"),
                "upstream_id": a.get("upstream_id"),
                "slug": a.get("slug"),
                "symbol": a.get("symbol"),
                "name": a.get("name"),
                "listing_status": a.get("listing_status"),
                "rank": a.get("rank"),
                "category": a.get("category"),
                "tags": a.get("tags", []),
                "status": a.get("status"),
            },
            "added_at": mem.get("added_at"),
            "quote": quote_payload,
        })

    response = {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None},
        "data": {
            "category": {
                "id": cat.get("id"),
                "upstream_id": cat.get("upstream_id"),
                "name": cat.get("name"),
                "slug": cat.get("slug"),
                "description": cat.get("description"),
                "num_tokens": cat.get("num_tokens"),
                "status": cat.get("status"),
                "last_synced_at": cat.get("last_synced_at"),
                "created_at": cat.get("created_at"),
                "updated_at": cat.get("updated_at"),
            },
            "members": members_out,
            "pagination": {
                "start": si,
                "limit": li,
                "total": total_members,
                "has_more": (start_idx + li) < total_members,
            }
        }
    }

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr

    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))

    # write-through cache (short TTL)
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(seconds=60)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        # lifecycle transition expired->valid allowed; keep same id
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def cryptoCurrencyMap(listing_status=None, start=None, limit=None, sort=None, symbol=None, aux=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str) or not x:
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date().isoformat()

    def _month_bucket(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # ---- Validate
    if listing_status is not None and not isinstance(listing_status, str):
        return _err("VALIDATION_ERROR", "listing_status must be a string")
    if start is not None and not isinstance(start, (int, float)):
        return _err("VALIDATION_ERROR", "start must be a number")
    if limit is not None and not isinstance(limit, (int, float)):
        return _err("VALIDATION_ERROR", "limit must be a number")
    if sort is not None and not isinstance(sort, str):
        return _err("VALIDATION_ERROR", "sort must be a string")
    if symbol is not None and not isinstance(symbol, str):
        return _err("VALIDATION_ERROR", "symbol must be a string")
    if aux is not None and not isinstance(aux, str):
        return _err("VALIDATION_ERROR", "aux must be a string")

    start_i = None
    limit_i = None
    if start is not None:
        if int(start) != start or start < 1:
            return _err("VALIDATION_ERROR", "start must be an integer >= 1")
        start_i = int(start)
    if limit is not None:
        if int(limit) != limit or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
        limit_i = int(limit)
    if limit_i is not None and limit_i > 5000:
        return _err("VALIDATION_ERROR", "limit too large")

    allowed_listing = {"active", "inactive", "untracked"}
    if listing_status is not None:
        ls = listing_status.strip().lower()
        if ls not in allowed_listing:
            return _err("VALIDATION_ERROR", "Unsupported listing_status")
        listing_status = ls

    allowed_sort = {None, "cmc_rank", "id", "name", "symbol"}
    if sort is not None:
        srt = sort.strip()
        if srt not in allowed_sort:
            return _err("VALIDATION_ERROR", "Unsupported sort")
        sort = srt

    aux_fields = set()
    if aux is not None and aux.strip():
        aux_fields = {a.strip() for a in aux.split(",") if a.strip()}
        # allow any aux; we just project from metadata safely

    # ---- Ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and k.get("id"):
            key = k
            break
    if not key:
        return _err("UNAUTHORIZED", "No active API key available")

    last = _parse_dt(key.get("last_request_at"))
    if last is None or _minute_bucket(last) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last is None or _day_bucket(last) != _day_bucket(now):
        key["requests_today"] = 0
    if last is None or _month_bucket(last) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_lim = key.get("requests_per_minute_limit", 0)
    rpd_lim = key.get("requests_per_day_limit", 0)
    mcred_lim = key.get("monthly_credit_limit", 0)
    if not isinstance(rpm_lim, int) or rpm_lim < 0:
        rpm_lim = 0
    if not isinstance(rpd_lim, int) or rpd_lim < 0:
        rpd_lim = 0
    if not isinstance(mcred_lim, int) or mcred_lim < 0:
        mcred_lim = 0

    def _deny(kind, api_code, msg):
        request_logs = _load("request_logs.json")
        if not isinstance(request_logs, list):
            request_logs = []
        rid = _gen_id("req")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": "cryptoCurrencyMap",
            "request_params": {k: v for k, v in {"listing_status": listing_status, "start": start_i, "limit": limit_i, "sort": sort, "symbol": symbol, "aux": aux}.items() if v is not None},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": kind,
            "error_message": msg,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys)
        return _err(api_code, msg)

    if rpm_lim > 0 and int(key.get("requests_this_minute", 0)) >= rpm_lim:
        return _deny("rate_limit", "RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if rpd_lim > 0 and int(key.get("requests_today", 0)) >= rpd_lim:
        return _deny("rate_limit", "RATE_LIMIT", "Rate limit exceeded (per-day)")

    credits_charged = 1
    if mcred_lim > 0 and int(key.get("credits_month_to_date", 0)) + credits_charged > mcred_lim:
        return _deny("quota_exceeded", "QUOTA_EXCEEDED", "Monthly credit limit exceeded")

    # ---- Read assets
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []

    rows = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("entity_type") != "cryptocurrency":
            continue
        if a.get("status") == "deleted":
            continue
        if listing_status is not None and a.get("listing_status") != listing_status:
            continue
        if symbol is not None and symbol.strip():
            if (a.get("symbol") or "").upper() != symbol.strip().upper():
                continue
        rows.append(a)

    # Sorting
    if sort is None or sort == "id":
        rows.sort(key=lambda r: (str(r.get("upstream_id") or ""), str(r.get("id") or "")))
    elif sort == "name":
        rows.sort(key=lambda r: (str(r.get("name") or ""), str(r.get("upstream_id") or "")))
    elif sort == "symbol":
        rows.sort(key=lambda r: (str(r.get("symbol") or ""), str(r.get("upstream_id") or "")))
    elif sort == "cmc_rank":
        # rank nulls last
        rows.sort(key=lambda r: (r.get("rank") is None, r.get("rank") if isinstance(r.get("rank"), int) else 10**12, str(r.get("upstream_id") or "")))

    total = len(rows)
    s = start_i if start_i is not None else 1
    l = limit_i if limit_i is not None else 100
    offset = s - 1
    page = rows[offset: offset + l]
    has_more = offset + l < total

    def _project(a):
        out = {
            "id": str(a.get("upstream_id")),
            "name": a.get("name"),
            "symbol": a.get("symbol"),
            "slug": a.get("slug"),
            "rank": a.get("rank"),
            "is_active": True if a.get("listing_status") == "active" else False,
            "first_historical_data": (a.get("metadata") or {}).get("first_historical_data") if isinstance(a.get("metadata"), dict) else None,
            "last_historical_data": (a.get("metadata") or {}).get("last_historical_data") if isinstance(a.get("metadata"), dict) else None,
            "platform": (a.get("metadata") or {}).get("platform") if isinstance(a.get("metadata"), dict) else None,
        }
        if aux_fields:
            md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
            for k in aux_fields:
                if k in md:
                    out[k] = md.get(k)
        return out

    data = [_project(a) for a in page]

    # ---- Persist usage and log
    key["requests_this_minute"] = int(key.get("requests_this_minute", 0)) + 1
    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0)) + credits_charged
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    rid = _gen_id("req")
    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": rid,
        "api_key_id": key["id"],
        "tool_name": "cryptoCurrencyMap",
        "request_params": {k: v for k, v in {"listing_status": listing_status, "start": s, "limit": l, "sort": sort, "symbol": symbol, "aux": aux}.items() if v is not None},
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": credits_charged,
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)

    return {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None, "elapsed": duration_ms, "credit_count": credits_charged},
        "data": data,
        "metadata": {"start": s, "limit": l, "total_count": total, "has_more": has_more}
    }

def getCryptoMetadata(symbol=None, id=None, slug=None, address=None, aux=None, skip_invalid=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

