    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str) or not x:
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date().isoformat()

    def _month_bucket(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:24]}"

    # ---- Validate
    for nm, val in (("symbol", symbol), ("id", id), ("slug", slug), ("address", address), ("aux", aux)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string")
    if skip_invalid is not None and not isinstance(skip_invalid, bool):
        return _err("VALIDATION_ERROR", "skip_invalid must be a boolean")

    if symbol is None and id is None and slug is None and address is None:
        return _err("VALIDATION_ERROR", "At least one identifier (symbol, id, slug, address) must be provided")

    # Parse identifier lists: accept comma-separated strings
    def _split_list(s):
        if s is None:
            return []
        items = [x.strip() for x in s.split(",")]
        return [x for x in items if x]

    symbols = [x.upper() for x in _split_list(symbol)]
    ids = _split_list(id)
    slugs = _split_list(slug)
    addresses = _split_list(address)

    # basic address validation (EVM-style hex) but allow non-hex addresses by skipping only if malformed and skip_invalid true
    evm_re = re.compile(r"^(0x)?[0-9a-fA-F]{40}$")
    for a in addresses:
        if not evm_re.match(a):
            if skip_invalid:
                # drop malformed addresses
                addresses = [x for x in addresses if x != a]
            else:
                return _err("VALIDATION_ERROR", "address is malformed; expected 0x + 40 hex chars")

    aux_fields = set()
    if aux is not None and aux.strip():
