    by_symbol = {}
    by_slug = {}
    for a in cryptos:
        sym = a.get("symbol")
        if isinstance(sym, str) and sym:
            by_symbol.setdefault(sym.upper(), []).append(a)
        s = a.get("slug")
        if isinstance(s, str) and s:
            by_slug.setdefault(s, []).append(a)

    def _addresses_for_asset(a):
        md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
        addrs = set()
        plat = md.get("platform")
        if isinstance(plat, dict):
            ca = plat.get("contract_address")
            if isinstance(ca, str) and ca:
                addrs.add(ca.lower())
        cas = md.get("contract_addresses")
        if isinstance(cas, list):
            for x in cas:
                if isinstance(x, str) and x:
                    addrs.add(x.lower())
                elif isinstance(x, dict):
                    ca = x.get("contract_address") or x.get("address")
                    if isinstance(ca, str) and ca:
                        addrs.add(ca.lower())
        return addrs

    by_address = {}
    for a in cryptos:
        for addr in _addresses_for_asset(a):
            by_address.setdefault(addr, []).append(a)

    requested = []
    # preserve order: ids first, symbols, slugs, addresses
    for x in ids:
        requested.append(("id", x))
    for x in symbols:
        requested.append(("symbol", x))
    for x in slugs:
        requested.append(("slug", x))
    for x in addresses:
        requested.append(("address", x.lower()))

    result = {}
    unresolved = []

    def _project_asset(a):
        md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
        out = {
            "id": str(a.get("upstream_id")),
            "name": a.get("name"),
            "symbol": a.get("symbol"),
            "slug": a.get("slug"),
            "category": a.get("category"),
            "description": md.get("description"),
            "logo": md.get("logo"),
            "urls": md.get("urls"),
            "platform": md.get("platform"),
            "tags": a.get("tags") if isinstance(a.get("tags"), list) else [],
        }
        if aux_fields:
            for k in aux_fields:
                if k in md:
                    out[k] = md.get(k)
        return out

    for kind, val in requested:
        matches = []
        if kind == "id":
            a = by_up_id.get(str(val))
            matches = [a] if a else []
        elif kind == "symbol":
            matches = by_symbol.get(val.upper(), [])
        elif kind == "slug":
            matches = by_slug.get(val, [])
        elif kind == "address":
            matches = by_address.get(val.lower(), [])

        if not matches:
            unresolved.append({"type": kind, "value": val})
            continue
        # if ambiguous (multiple matches) and skip_invalid is false => validation error
        if len(matches) > 1 and not skip_invalid:
            return _err("VALIDATION_ERROR", f"Ambiguous {kind} identifier: {val}")
        # pick deterministic: smallest upstream_id
        matches_sorted = sorted(matches, key=lambda a: (str(a.get("upstream_id") or ""), str(a.get("id") or "")))
        a = matches_sorted[0]
        result[str(a.get("upstream_id"))] = _project_asset(a)

    if unresolved and not skip_invalid:
        return _err("NOT_FOUND", "One or more identifiers could not be resolved", unresolved=unresolved)

    # ---- Persist usage and log
    key["requests_this_minute"] = int(key.get("requests_this_minute", 0)) + 1
    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0)) + credits_charged
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    rid = _gen_id("req")
    duration_ms = max(0, int((time.time() - t0) * 1000))
    request_logs.append({
        "id": rid,
        "api_key_id": key["id"],
        "tool_name": "getCryptoMetadata",
        "request_params": {k: v for k, v in {"symbol": symbol, "id": id, "slug": slug, "address": address, "aux": aux, "skip_invalid": skip_invalid}.items() if v is not None},
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": credits_charged,
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)

    return {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None, "elapsed": duration_ms, "credit_count": credits_charged},
        "data": result
    }

def allCryptocurrencyListings(start=None, limit=None, price_min=None, price_max=None, market_cap_min=None, market_cap_max=None, volume_24h_min=None, volume_24h_max=None, circulating_supply_min=None, circulating_supply_max=None, percent_change_24h_min=None, percent_change_24h_max=None, convert=None, convert_id=None, sort=None, sort_dir=None, cryptocurrency_type=None, tag=None, aux=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _minute_bucket(dt):
        return dt.strftime("%Y-%m-%dT%H:%MZ")

    def _day_bucket(dt):
        return dt.strftime("%Y-%m-%d")

    def _month_bucket(dt):
        return dt.strftime("%Y-%m")

    def _stable_fingerprint(tool_name, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool_name + "|" + payload).encode("utf-8")).hexdigest()

    def _norm_aux(aux_s):
        if aux_s is None:
            return []
        if not isinstance(aux_s, str):
            return None
        parts = [p.strip() for p in aux_s.split(",") if p.strip()]
        # allow empty -> []
        return parts

    def _project_listing(asset_row, md_row, convert_sym, convert_uid, aux_list):
        # shape similar to CMC: basic identity + quote; include aux-controlled fields
        out = {
            "id": asset_row.get("upstream_id"),
            "name": asset_row.get("name"),
            "symbol": asset_row.get("symbol"),
            "slug": asset_row.get("slug"),
            "cmc_rank": asset_row.get("rank"),
            "last_updated": (md_row.get("aux_fields", {}) or {}).get("last_updated") if md_row else None,
        }

        # date_added from metadata (if present)
        meta = asset_row.get("metadata", {}) or {}
        out["date_added"] = meta.get("date_added") or meta.get("first_historical_data") or None

        # "tags" and "platform" etc are aux-dependent in real API; we include only requested
        if aux_list:
            if "tags" in aux_list:
                out["tags"] = asset_row.get("tags", []) or []
            if "platform" in aux_list:
                out["platform"] = meta.get("platform")
            if "is_active" in aux_list:
                out["is_active"] = 1 if asset_row.get("listing_status") == "active" else 0
            if "status" in aux_list:
                out["listing_status"] = asset_row.get("listing_status")

        quote = {}
        if md_row:
            numeric = md_row.get("numeric_fields", {}) or {}
            # The stored md row is already for requested convert_* (if present). Use those fields.
            quote_ccy = convert_sym or convert_uid or "USD"
            quote[quote_ccy] = numeric
            # Provide commonly expected top-level supply fields when present
            for k in ("circulating_supply", "total_supply", "max_supply"):
                if k in numeric:
                    out[k] = numeric.get(k)
            # Provide num_market_pairs, etc from aux_fields when present and requested
            auxf = md_row.get("aux_fields", {}) or {}
            if aux_list:
                if "num_market_pairs" in aux_list and "num_market_pairs" in auxf:
                    out["num_market_pairs"] = auxf.get("num_market_pairs")
                if "market_cap_by_total_supply" in aux_list and "market_cap_by_total_supply" in numeric:
                    out["market_cap_by_total_supply"] = numeric.get("market_cap_by_total_supply")
        out["quote"] = quote
        return out

    t0 = time.time()
    tool_name = "allCryptocurrencyListings"

    # --- Validate params (additionalProperties=false is enforced by signature) ---
    allowed_sort = {
        "market_cap", "name", "symbol", "date_added", "price", "circulating_supply", "total_supply", "max_supply",
        "num_market_pairs", "volume_24h", "percent_change_1h", "percent_change_24h", "percent_change_7d"
    }
    allowed_sort_dir = {"asc", "desc"}

    if start is None:
        start_val = 1
    else:
        if not isinstance(start, (int, float)) or isinstance(start, bool):
            return _err("VALIDATION_ERROR", "start must be a number (1-based).")
        start_val = int(start)
        if start_val < 1:
            return _err("VALIDATION_ERROR", "start must be >= 1.")

    if limit is None:
        limit_val = 100
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number.")
        limit_val = int(limit)
        if limit_val < 1 or limit_val > 5000:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 5000.")

    def _check_range(a, b, name):
        if a is not None and (not isinstance(a, (int, float)) or isinstance(a, bool)):
            return _err("VALIDATION_ERROR", f"{name}_min must be a number.")
        if b is not None and (not isinstance(b, (int, float)) or isinstance(b, bool)):
            return _err("VALIDATION_ERROR", f"{name}_max must be a number.")
        if a is not None and b is not None and float(a) > float(b):
            return _err("VALIDATION_ERROR", f"Invalid range: {name}_min > {name}_max.")
        return None

    for nm, a, b in [
        ("price", price_min, price_max),
        ("market_cap", market_cap_min, market_cap_max),
        ("volume_24h", volume_24h_min, volume_24h_max),
        ("circulating_supply", circulating_supply_min, circulating_supply_max),
        ("percent_change_24h", percent_change_24h_min, percent_change_24h_max),
    ]:
        e = _check_range(a, b, nm)
        if e:
            return e

    if convert is not None and not isinstance(convert, str):
        return _err("VALIDATION_ERROR", "convert must be a string.")
    if convert_id is not None and not isinstance(convert_id, str):
        return _err("VALIDATION_ERROR", "convert_id must be a string.")
    if convert is not None and convert_id is not None:
        return _err("VALIDATION_ERROR", "Provide only one of convert or convert_id.")

    if sort is None:
        sort_val = "market_cap"
    else:
        if not isinstance(sort, str) or sort not in allowed_sort:
            return _err("VALIDATION_ERROR", "Invalid sort.")
        sort_val = sort

    if sort_dir is None:
        sort_dir_val = "desc"
    else:
        if not isinstance(sort_dir, str) or sort_dir not in allowed_sort_dir:
            return _err("VALIDATION_ERROR", "Invalid sort_dir.")
        sort_dir_val = sort_dir

    if cryptocurrency_type is not None and not isinstance(cryptocurrency_type, str):
        return _err("VALIDATION_ERROR", "cryptocurrency_type must be a string.")
    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "tag must be a string.")

    aux_list = _norm_aux(aux)
    if aux_list is None:
        return _err("VALIDATION_ERROR", "aux must be a comma-separated string.")

    # --- Resolve an active API key (ambient auth) ---
    now = _now_utc()
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _pick_authorized_key():
        for k in api_keys:
            if k.get("status") == "active":
                return k
        return None

    key = _pick_authorized_key()
    if not key:
        # still must log the call once; but we have no key to reference -> cannot create valid fk row
        # In this datastore, enforce fk strictly by returning UNAUTHORIZED without logging.
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    # --- Enforce window resets and quotas/rate limits ---
    last_dt = _parse_dt(key.get("last_request_at"))
    # reset minute/day/month buckets if boundary crossed
    if last_dt is None:
        last_min = None
        last_day = None
        last_month = None
    else:
        last_min = _minute_bucket(last_dt.astimezone(datetime.timezone.utc))
        last_day = _day_bucket(last_dt.astimezone(datetime.timezone.utc))
        last_month = _month_bucket(last_dt.astimezone(datetime.timezone.utc))
    now_min = _minute_bucket(now)
    now_day = _day_bucket(now)
    now_month = _month_bucket(now)

    key_changed = False
    if last_min != now_min:
        if int(key.get("requests_this_minute", 0) or 0) != 0:
            key["requests_this_minute"] = 0
            key_changed = True
    if last_day != now_day:
        if int(key.get("requests_today", 0) or 0) != 0:
            key["requests_today"] = 0
            key_changed = True
    if last_month != now_month:
        if int(key.get("credits_month_to_date", 0) or 0) != 0:
            key["credits_month_to_date"] = 0
            key_changed = True

    rpm_lim = int(key.get("requests_per_minute_limit", 0) or 0)
    rpd_lim = int(key.get("requests_per_day_limit", 0) or 0)
    cred_lim = int(key.get("monthly_credit_limit", 0) or 0)

    # credits charged for this endpoint: 1 base + limit/1000 (rounded up) to emulate heavier listing calls
    credits_charged = 1 + int((max(limit_val, 1) - 1) / 1000)

    if rpm_lim > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_lim:
        # log denied
        rid = "req_" + uuid.uuid4().hex
        req_row = {
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": tool_name,
            "request_params": {
                "start": start if start is not None else None,
                "limit": limit if limit is not None else None,
                "price_min": price_min,
                "price_max": price_max,
                "market_cap_min": market_cap_min,
                "market_cap_max": market_cap_max,
                "volume_24h_min": volume_24h_min,
                "volume_24h_max": volume_24h_max,
                "circulating_supply_min": circulating_supply_min,
                "circulating_supply_max": circulating_supply_max,
                "percent_change_24h_min": percent_change_24h_min,
                "percent_change_24h_max": percent_change_24h_max,
                "convert": convert,
                "convert_id": convert_id,
                "sort": sort,
                "sort_dir": sort_dir,
                "cryptocurrency_type": cryptocurrency_type,
                "tag": tag,
                "aux": aux
            },
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "rate_limit",
            "error_message": "requests_per_minute_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(req_row)
        _save("request_logs.json", request_logs)
        if key_changed:
            key["updated_at"] = _iso(now)
            _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute).")

    if rpd_lim > 0 and int(key.get("requests_today", 0) or 0) >= rpd_lim:
        rid = "req_" + uuid.uuid4().hex
        req_row = {
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": tool_name,
            "request_params": {
                "start": start if start is not None else None,
                "limit": limit if limit is not None else None,
                "price_min": price_min,
                "price_max": price_max,
                "market_cap_min": market_cap_min,
                "market_cap_max": market_cap_max,
                "volume_24h_min": volume_24h_min,
                "volume_24h_max": volume_24h_max,
                "circulating_supply_min": circulating_supply_min,
                "circulating_supply_max": circulating_supply_max,
                "percent_change_24h_min": percent_change_24h_min,
                "percent_change_24h_max": percent_change_24h_max,
                "convert": convert,
                "convert_id": convert_id,
                "sort": sort,
                "sort_dir": sort_dir,
                "cryptocurrency_type": cryptocurrency_type,
                "tag": tag,
                "aux": aux
            },
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": "requests_per_day_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(req_row)
        _save("request_logs.json", request_logs)
        if key_changed:
            key["updated_at"] = _iso(now)
            _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    if cred_lim > 0 and (int(key.get("credits_month_to_date", 0) or 0) + credits_charged) > cred_lim:
        rid = "req_" + uuid.uuid4().hex
        req_row = {
            "id": rid,
            "api_key_id": key["id"],
            "tool_name": tool_name,
            "request_params": {
                "start": start if start is not None else None,
                "limit": limit if limit is not None else None,
                "price_min": price_min,
                "price_max": price_max,
                "market_cap_min": market_cap_min,
                "market_cap_max": market_cap_max,
                "volume_24h_min": volume_24h_min,
                "volume_24h_max": volume_24h_max,
                "circulating_supply_min": circulating_supply_min,
                "circulating_supply_max": circulating_supply_max,
                "percent_change_24h_min": percent_change_24h_min,
                "percent_change_24h_max": percent_change_24h_max,
                "convert": convert,
                "convert_id": convert_id,
                "sort": sort,
                "sort_dir": sort_dir,
                "cryptocurrency_type": cryptocurrency_type,
                "tag": tag,
                "aux": aux
            },
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        request_logs.append(req_row)
        _save("request_logs.json", request_logs)
        if key_changed:
            key["updated_at"] = _iso(now)
            _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded.")

    # --- Cache lookup ---
    normalized_params = {
        "start": start_val,
        "limit": limit_val,
        "price_min": float(price_min) if price_min is not None else None,
        "price_max": float(price_max) if price_max is not None else None,
        "market_cap_min": float(market_cap_min) if market_cap_min is not None else None,
        "market_cap_max": float(market_cap_max) if market_cap_max is not None else None,
        "volume_24h_min": float(volume_24h_min) if volume_24h_min is not None else None,
        "volume_24h_max": float(volume_24h_max) if volume_24h_max is not None else None,
        "circulating_supply_min": float(circulating_supply_min) if circulating_supply_min is not None else None,
        "circulating_supply_max": float(circulating_supply_max) if circulating_supply_max is not None else None,
        "percent_change_24h_min": float(percent_change_24h_min) if percent_change_24h_min is not None else None,
        "percent_change_24h_max": float(percent_change_24h_max) if percent_change_24h_max is not None else None,
        "convert": convert,
        "convert_id": convert_id,
        "sort": sort_val,
        "sort_dir": sort_dir_val,
        "cryptocurrency_type": cryptocurrency_type,
        "tag": tag,
        "aux": aux or ""
    }
    fp = _stable_fingerprint(tool_name, normalized_params)
    cache_key = f"{tool_name}:{fp}"

    cached_responses = _load("cached_responses.json")
    if not isinstance(cached_responses, list):
        cached_responses = []

    cache_row = None
    for cr in cached_responses:
        if cr.get("tool_name") == tool_name and cr.get("params_fingerprint") == fp:
            cache_row = cr
            break

    if cache_row and cache_row.get("status") == "valid":
        exp = _parse_dt(cache_row.get("expires_at"))
        if exp and exp > now:
            # consume quota/counters even on cache hit
            key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
            key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
            key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + credits_charged
            key["last_request_at"] = _iso(now)
            key["updated_at"] = _iso(now)
            _save("api_keys.json", api_keys)

            rid = "req_" + uuid.uuid4().hex
            req_row = {
                "id": rid,
                "api_key_id": key["id"],
                "tool_name": tool_name,
                "request_params": {
                    "start": start if start is not None else None,
                    "limit": limit if limit is not None else None,
                    "price_min": price_min,
                    "price_max": price_max,
                    "market_cap_min": market_cap_min,
                    "market_cap_max": market_cap_max,
                    "volume_24h_min": volume_24h_min,
                    "volume_24h_max": volume_24h_max,
                    "circulating_supply_min": circulating_supply_min,
                    "circulating_supply_max": circulating_supply_max,
                    "percent_change_24h_min": percent_change_24h_min,
                    "percent_change_24h_max": percent_change_24h_max,
                    "convert": convert,
                    "convert_id": convert_id,
                    "sort": sort,
                    "sort_dir": sort_dir,
                    "cryptocurrency_type": cryptocurrency_type,
                    "tag": tag,
                    "aux": aux
                },
                "cache_key": cache_key,
                "cache_hit": True,
                "upstream_http_status": cache_row.get("http_status"),
                "credits_charged": credits_charged,
                "duration_ms": int((time.time() - t0) * 1000),
                "error_code": None,
                "error_message": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            request_logs.append(req_row)
            _save("request_logs.json", request_logs)

            body = cache_row.get("response_body")
            if isinstance(body, dict):
                return body
            return {"data": [], "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}, "meta": {"cached": True}}

    # --- Build response from datastore ---
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    mds = _load("market_data.json")
    if not isinstance(mds, list):
        mds = []

    # Select active cryptocurrencies
    cryptos = [a for a in assets if a.get("entity_type") == "cryptocurrency" and a.get("listing_status") == "active" and a.get("status") != "deleted"]

    # Filter by cryptocurrency_type and tag
    if cryptocurrency_type:
        cryptos = [a for a in cryptos if (a.get("category") == cryptocurrency_type) or (cryptocurrency_type in (a.get("tags") or []))]
    if tag:
        cryptos = [a for a in cryptos if tag in (a.get("tags") or [])]

    # For each crypto pick latest listings row with matching convert params if provided
    # Convert matching: prefer convert_symbol, else convert_upstream_id, else any (fallback None)
    def _md_matches(md):
        if md.get("record_type") != "crypto_listings_latest_row":
            return False
        if convert is not None and md.get("convert_symbol") != convert:
            return False
        if convert_id is not None and md.get("convert_upstream_id") != convert_id:
            return False
        if convert is None and convert_id is None:
            # accept any row, but prefer those with no convert fields
            return True
        return True

    latest_by_asset = {}
    for md in mds:
        if not _md_matches(md):
            continue
        pa = md.get("primary_asset_id")
        if not pa:
            continue
        asof = _parse_dt(md.get("as_of"))
        if not asof:
            continue
        cur = latest_by_asset.get(pa)
        if not cur:
            latest_by_asset[pa] = md
        else:
            cur_asof = _parse_dt(cur.get("as_of"))
            if cur_asof and asof > cur_asof:
                latest_by_asset[pa] = md
            elif cur_asof is None:
                latest_by_asset[pa] = md
            else:
                # if as_of tie, prefer one without convert fields when no convert requested
                if convert is None and convert_id is None:
                    cur_score = (1 if cur.get("convert_symbol") or cur.get("convert_upstream_id") else 0)
                    md_score = (1 if md.get("convert_symbol") or md.get("convert_upstream_id") else 0)
                    if md_score < cur_score:
                        latest_by_asset[pa] = md

    # Apply numeric filters based on md.numeric_fields
    def _get_num(md, path):
        if not md:
            return None
        nf = md.get("numeric_fields", {}) or {}
        v = nf.get(path)
        try:
            return float(v) if v is not None else None
        except Exception:
            return None

    filtered = []
    for a in cryptos:
        md = latest_by_asset.get(a.get("id"))
        # numeric filter keys commonly: price, market_cap, volume_24h, circulating_supply, percent_change_24h
        p = _get_num(md, "price")
        mc = _get_num(md, "market_cap")
        v24 = _get_num(md, "volume_24h")
        cs = _get_num(md, "circulating_supply")
        pc24 = _get_num(md, "percent_change_24h")

        def _in_range(val, mn, mx):
            if mn is not None:
                if val is None or val < float(mn):
                    return False
            if mx is not None:
                if val is None or val > float(mx):
                    return False
            return True

        if not _in_range(p, price_min, price_max):
            continue
        if not _in_range(mc, market_cap_min, market_cap_max):
            continue
        if not _in_range(v24, volume_24h_min, volume_24h_max):
            continue
        if not _in_range(cs, circulating_supply_min, circulating_supply_max):
            continue
        if not _in_range(pc24, percent_change_24h_min, percent_change_24h_max):
            continue

        filtered.append((a, md))

    # Sorting
    def _sort_key(pair):
        a, md = pair
        meta = a.get("metadata", {}) or {}
        nf = md.get("numeric_fields", {}) if md else {}
        auxf = md.get("aux_fields", {}) if md else {}
        if sort_val == "name":
            return (a.get("name") or "")
        if sort_val == "symbol":
            return (a.get("symbol") or "")
        if sort_val == "date_added":
            d = meta.get("date_added") or meta.get("first_historical_data") or ""
            return d
        if sort_val == "market_cap":
            return _get_num(md, "market_cap") if md else float("-inf")
        if sort_val == "price":
            return _get_num(md, "price") if md else float("-inf")
        if sort_val == "circulating_supply":
            return _get_num(md, "circulating_supply") if md else float("-inf")
        if sort_val == "total_supply":
            return _get_num(md, "total_supply") if md else float("-inf")
        if sort_val == "max_supply":
            return _get_num(md, "max_supply") if md else float("-inf")
        if sort_val == "num_market_pairs":
            v = auxf.get("num_market_pairs")
            try:
                return int(v) if v is not None else -1
            except Exception:
                return -1
        if sort_val == "volume_24h":
            return _get_num(md, "volume_24h") if md else float("-inf")
        if sort_val == "percent_change_1h":
            return _get_num(md, "percent_change_1h") if md else float("-inf")
        if sort_val == "percent_change_24h":
            return _get_num(md, "percent_change_24h") if md else float("-inf")
        if sort_val == "percent_change_7d":
            return _get_num(md, "percent_change_7d") if md else float("-inf")
        return 0

    reverse = (sort_dir_val == "desc")
    try:
        filtered.sort(key=_sort_key, reverse=reverse)
    except Exception:
        return _err("VALIDATION_ERROR", "Unable to sort with requested parameters.")

    total = len(filtered)
    start_idx = start_val - 1
    end_idx = start_idx + limit_val
    page = filtered[start_idx:end_idx]
    has_more = end_idx < total

    data = [_project_listing(a, md, convert, convert_id, aux_list) for (a, md) in page]

    response_body = {
        "data": data,
        "status": {"timestamp": _iso(now), "error_code": None, "error_message": None},
        "meta": {
            "start": start_val,
            "limit": limit_val,
            "total": total,
            "has_more": has_more
        }
    }

    # --- write cache (short ttl) ---
    expires_at = now + datetime.timedelta(seconds=60)
    if cache_row and cache_row.get("status") in ("valid", "expired"):
        cache_row["request_params"] = normalized_params
        cache_row["response_body"] = response_body
        cache_row["http_status"] = 200
        cache_row["etag"] = cache_row.get("etag")
        cache_row["expires_at"] = _iso(expires_at)
        cache_row["status"] = "valid"
        cache_row["updated_at"] = _iso(now)
    else:
        cache_row = {
            "id": "cache_" + uuid.uuid4().hex,
            "tool_name": tool_name,
            "params_fingerprint": fp,
            "request_params": normalized_params,
            "response_body": response_body,
            "http_status": 200,
            "etag": None,
            "expires_at": _iso(expires_at),
            "status": "valid",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        cached_responses.append(cache_row)
    _save("cached_responses.json", cached_responses)

    # --- consume counters and log request ---
    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + credits_charged
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    rid = "req_" + uuid.uuid4().hex
    req_params_logged = {
        "start": start if start is not None else None,
        "limit": limit if limit is not None else None,
        "price_min": price_min,
        "price_max": price_max,
        "market_cap_min": market_cap_min,
        "market_cap_max": market_cap_max,
        "volume_24h_min": volume_24h_min,
        "volume_24h_max": volume_24h_max,
        "circulating_supply_min": circulating_supply_min,
        "circulating_supply_max": circulating_supply_max,
        "percent_change_24h_min": percent_change_24h_min,
        "percent_change_24h_max": percent_change_24h_max,
        "convert": convert,
        "convert_id": convert_id,
        "sort": sort,
        "sort_dir": sort_dir,
        "cryptocurrency_type": cryptocurrency_type,
        "tag": tag,
        "aux": aux
    }
    req_row = {
        "id": rid,
        "api_key_id": key["id"],
        "tool_name": tool_name,
        "request_params": req_params_logged,
        "cache_key": cache_key,
        "cache_hit": False,
        "upstream_http_status": 200,
        "credits_charged": credits_charged,
        "duration_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    return response_body

def cryptoQuotesLatest(id=None, slug=None, symbol=None, convert=None, convert_id=None, aux=None, skip_invalid=None, **_extra):
    import json, os, datetime, time, hashlib, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "cryptoQuotesLatest"

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt.year, dt.month)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool_name, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool_name + "|" + payload).encode("utf-8")).hexdigest()

    def _split_csv(v):
        if v is None:
            return []
        if not isinstance(v, str):
            return None
        parts = [p.strip() for p in v.split(",") if p.strip()]
        return parts

    # ---- validate inputs (relax convert_id to allow numbers)
    for nm, vv in (("id", id), ("slug", slug), ("symbol", symbol), ("convert", convert), ("aux", aux)):
        if vv is not None and not isinstance(vv, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string")
    if skip_invalid is not None and not isinstance(skip_invalid, bool):
        return _err("VALIDATION_ERROR", "skip_invalid must be a boolean")
    if convert_id is not None and not isinstance(convert_id, str):
        if isinstance(convert_id, (int, float)) and int(convert_id) == convert_id:
            convert_id = str(int(convert_id))
        else:
            return _err("VALIDATION_ERROR", "convert_id must be a string.")

    if convert is not None:
        convert = convert.strip().upper()
        if not convert:
            return _err("VALIDATION_ERROR", "convert must be a non-empty string")
        if not re.fullmatch(r"[A-Z0-9]{2,15}", convert):
            return _err("VALIDATION_ERROR", "convert is malformed")
    if convert_id is not None:
        convert_id = convert_id.strip()
        if not convert_id:
            return _err("VALIDATION_ERROR", "convert_id must be a non-empty string")

    ids = _split_csv(id)
    slugs = _split_csv(slug)
    symbols = _split_csv(symbol)
    if ids is None or slugs is None or symbols is None:
        return _err("VALIDATION_ERROR", "id/slug/symbol must be a comma-separated string")
    if not ids and not slugs and not symbols:
        return _err("VALIDATION_ERROR", "Provide at least one of id, slug, or symbol")

    aux_list = _split_csv(aux) if aux is not None else []
    if aux_list is None:
        return _err("VALIDATION_ERROR", "aux must be a comma-separated string")

    # ---- ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")
    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key["id"]

    last_req = _parse_iso(key.get("last_request_at"))
    if last_req is None or _minute_bucket(last_req) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last_req is None or _day_bucket(last_req) != _day_bucket(now):
        key["requests_today"] = 0
    if last_req is None or _month_bucket(last_req) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_limit = key.get("requests_per_minute_limit", 0) or 0
    day_limit = key.get("requests_per_day_limit", 0) or 0
    credit_limit = key.get("monthly_credit_limit", 0) or 0
    credits_charged = 1

    request_params = {}
    if id is not None: request_params["id"] = id
    if slug is not None: request_params["slug"] = slug
    if symbol is not None: request_params["symbol"] = symbol
    if convert is not None: request_params["convert"] = convert
    if convert_id is not None: request_params["convert_id"] = convert_id
    if aux is not None: request_params["aux"] = aux
    if skip_invalid is not None: request_params["skip_invalid"] = skip_invalid

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    log_row = {
        "id": _new_id("cmc_req"),
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": int(credits_charged),
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if isinstance(rpm_limit, int) and rpm_limit > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_limit:
        log_row["error_code"] = "rate_limited"
        log_row["error_message"] = "Per-minute request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if isinstance(day_limit, int) and day_limit > 0 and int(key.get("requests_today", 0) or 0) >= day_limit:
        log_row["error_code"] = "quota_exceeded"
        log_row["error_message"] = "Daily request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if isinstance(credit_limit, int) and credit_limit > 0 and (int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)) > credit_limit:
        log_row["error_code"] = "quota_exceeded"
        log_row["error_message"] = "Monthly credit limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # ---- cache
    norm_params = {"id": ids, "slug": slugs, "symbol": symbols}
    if convert is not None: norm_params["convert"] = convert
    if convert_id is not None: norm_params["convert_id"] = convert_id
    if aux_list: norm_params["aux"] = aux_list
    if skip_invalid is not None: norm_params["skip_invalid"] = bool(skip_invalid)
    fp = _stable_fingerprint(tool_name, norm_params)
    cache_key = f"{tool_name}:{fp}"
    log_row["cache_key"] = cache_key

    cached = _load("cached_responses.json")
    if not isinstance(cached, list):
        cached = []
    cache_entry = None
    for r in cached:
        if isinstance(r, dict) and r.get("tool_name") == tool_name and r.get("params_fingerprint") == fp:
            cache_entry = r
            break

    def _cache_valid(entry):
        if not entry or entry.get("status") != "valid":
            return False
        exp = _parse_iso(entry.get("expires_at"))
        return exp is not None and exp > now

    if _cache_valid(cache_entry):
        log_row["cache_hit"] = True
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        body = cache_entry.get("response_body")
        return {"data": body, "cache": {"hit": True, "id": cache_entry.get("id"), "expires_at": cache_entry.get("expires_at")}}

    # ---- resolve assets
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    cryptos = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "cryptocurrency" and a.get("status") != "deleted"]
    by_upstream_id = {a.get("upstream_id"): a for a in cryptos if isinstance(a.get("upstream_id"), str)}
    by_slug = {}
    by_symbol = {}
    for a in cryptos:
        if isinstance(a.get("slug"), str):
            by_slug[a["slug"].lower()] = a
        if isinstance(a.get("symbol"), str):
            by_symbol[a["symbol"].upper()] = a

    selected = []
    missing = []
    seen_asset_ids = set()

    def _add_asset(a):
        if not a:
            return
        aid = a.get("id")
        if not isinstance(aid, str) or aid in seen_asset_ids:
            return
        seen_asset_ids.add(aid)
        selected.append(a)

    for v in ids:
        a = by_upstream_id.get(v)
        if a is None:
            missing.append(v)
        else:
            _add_asset(a)
    for v in slugs:
        a = by_slug.get(v.lower())
        if a is None:
            missing.append(v)
        else:
            _add_asset(a)
    for v in symbols:
        a = by_symbol.get(v.upper())
        if a is None:
            missing.append(v)
        else:
            _add_asset(a)

    if missing and not skip_invalid:
        log_row["error_code"] = "not_found"
        log_row["error_message"] = "Unknown identifiers"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        request_logs.append(log_row)
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Unknown identifier(s)", missing=missing)

    # ---- latest quotes
    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    def _latest_quote(asset_id):
        best = None
        best_asof = None
        for row in mkt:
            if not isinstance(row, dict):
                continue
            if row.get("record_type") != "crypto_quote_latest":
                continue
            if row.get("primary_asset_id") != asset_id:
                continue
            if convert is not None and row.get("convert_symbol") != convert:
                continue
            if convert_id is not None and row.get("convert_upstream_id") != convert_id:
                continue
            if row.get("status") not in ("fresh", "stale"):
                continue
            asof = _parse_iso(row.get("as_of"))
            if asof is None:
                continue
            if best is None or asof > best_asof:
                best = row
                best_asof = asof
        return best

    data = {}
    for a in selected:
        q = _latest_quote(a.get("id"))
        quote_obj = None
        if isinstance(q, dict):
            quote_obj = {
                "numeric": q.get("numeric_fields"),
                "aux": q.get("aux_fields"),
                "as_of": q.get("as_of"),
                "convert": {"symbol": convert, "id": convert_id},
            }
        base = {
            "id": a.get("upstream_id"),
            "name": a.get("name"),
            "symbol": a.get("symbol"),
            "slug": a.get("slug"),
            "rank": a.get("rank"),
        }
        if aux_list:
            md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
            base["metadata"] = {}
            for k in aux_list:
                if k in md:
                    base["metadata"][k] = md.get(k)
        base["quote"] = quote_obj
        if isinstance(a.get("upstream_id"), str):
            data[a["upstream_id"]] = base

    resp_body = {"data": data, "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}}

    # store cache
    expires_at = now + datetime.timedelta(seconds=30)
    if cache_entry is None:
        cached.append({
            "id": _new_id("cmc_cache"),
            "tool_name": tool_name,
            "params_fingerprint": fp,
            "request_params": norm_params,
            "response_body": resp_body,
            "http_status": 200,
            "etag": None,
            "expires_at": _iso(expires_at),
            "status": "valid",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
    else:
        cache_entry["request_params"] = norm_params
        cache_entry["response_body"] = resp_body
        cache_entry["http_status"] = 200
        cache_entry["expires_at"] = _iso(expires_at)
        cache_entry["status"] = "valid"
        cache_entry["updated_at"] = _iso(now)
    _save("cached_responses.json", cached)

    log_row["duration_ms"] = int((time.time() - _t0) * 1000)
    request_logs.append(log_row)
    _save("request_logs.json", request_logs)
    return {"data": resp_body, "cache": {"hit": False, "stored": True, "expires_at": _iso(expires_at)}}

def dexInfo(id=None, aux=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "dexInfo"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")

        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    def _split_csv(v):
        if v is None:
            return []
        if not isinstance(v, str):
            return None
        parts = [p.strip() for p in v.split(",")]
        return [p for p in parts if p]

    # validate params
    request_params = {}
    if id is not None:
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string when provided")
        request_params["id"] = id.strip()
    if aux is not None:
        if not isinstance(aux, str):
            return _err("VALIDATION_ERROR", "aux must be a string when provided")
        request_params["aux"] = aux

    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    credits = 1
    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    # cache lookup
    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((time.time() - t0) * 1000))
                        return c["response_body"]
                break

    aux_set = _split_csv(aux)
    if aux_set is None:
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message="aux must be a comma-separated string")
        return _err("VALIDATION_ERROR", "aux must be a comma-separated string")

    allowed_aux = {"urls", "logo", "description", "fee", "tags", "platform", "social", "notice"}
    for a in aux_set:
        if a not in allowed_aux:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message=f"Invalid aux value: {a}")
            return _err("VALIDATION_ERROR", f"Invalid aux value: {a}")

    # resolve DEX assets by upstream_id (tool param id is upstream_id)
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []

    dex_rows = [r for r in assets if isinstance(r, dict) and r.get("entity_type") == "dex" and r.get("status") != "deleted"]

    if id is not None:
        wanted = id.strip()
        dex_rows = [r for r in dex_rows if str(r.get("upstream_id")) == wanted]

        if not dex_rows:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message=f"DEX id(s) not found: {wanted}")
            return _err("NOT_FOUND", f"DEX id(s) not found: {wanted}")

    def _project(r):
        md = r.get("metadata") if isinstance(r.get("metadata"), dict) else {}
        out = {
            "id": r.get("id"),
            "upstream_id": r.get("upstream_id"),
            "slug": r.get("slug"),
            "name": r.get("name"),
            "status": r.get("status"),
            "listing_status": r.get("listing_status"),
            "tags": r.get("tags", []),
            "last_synced_at": r.get("last_synced_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }
        if not aux_set:
            # default lightweight set similar to CMC metadata endpoints
            return out
        if "urls" in aux_set:
            out["urls"] = md.get("urls")
        if "logo" in aux_set:
            out["logo"] = md.get("logo")
        if "description" in aux_set:
            out["description"] = md.get("description")
        if "fee" in aux_set:
            out["fee"] = md.get("fee")
        if "platform" in aux_set:
            out["platform"] = md.get("platform")
        if "social" in aux_set:
            out["social"] = md.get("social")
        if "notice" in aux_set:
            out["notice"] = md.get("notice")
        if "tags" in aux_set:
            out["tags"] = r.get("tags", [])
        return out

    data = [_project(r) for r in sorted(dex_rows, key=lambda x: str(x.get("upstream_id") or ""))]

    response = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": data}

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr
    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))

    # cache write-through (longer TTL for metadata)
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(hours=6)
    fp = _stable_fingerprint(tool_name, request_params)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def dexListingsLatest(start=None, limit=None, sort=None, sort_dir=None, type=None, aux=None, convert_id=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "dexListingsLatest"

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt.year, dt.month)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    # Validate (schema says start/limit strings, but callers pass numbers; accept both)
    def _parse_pos_int(v, field, default):
        if v is None:
            return default, None
        if isinstance(v, (int, float)) and int(v) == v:
            iv = int(v)
            if iv < 1:
                return None, _err("VALIDATION_ERROR", f"{field} must be >= 1 (1-based)")
            return iv, None
        if isinstance(v, str):
            s = v.strip()
            if not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be an integer (1-based)")
            iv = int(s)
            if iv < 1:
                return None, _err("VALIDATION_ERROR", f"{field} must be >= 1 (1-based)")
            return iv, None
        return None, _err("VALIDATION_ERROR", f"{field} must be an integer (1-based)")

    start_i, e = _parse_pos_int(start, "start", 1)
    if e: return e
    limit_i, e = _parse_pos_int(limit, "limit", 100)
    if e: return e
    if limit_i < 1 or limit_i > 5000:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 5000")

    if sort is None:
        sort = "volume_24h"
    if sort_dir is None:
        sort_dir = "desc"
    if type is None:
        type = "all"
    if sort not in ("name", "volume_24h", "market_share", "num_markets"):
        return _err("VALIDATION_ERROR", "sort must be one of: name, volume_24h, market_share, num_markets")
    if sort_dir not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_dir must be one of: asc, desc")
    if type not in ("all", "orderbook", "swap", "aggregator"):
        return _err("VALIDATION_ERROR", "type must be one of: all, orderbook, swap, aggregator")
    if aux is not None and not isinstance(aux, str):
        return _err("VALIDATION_ERROR", "aux must be a string")
    if convert_id is not None and not isinstance(convert_id, str):
        if isinstance(convert_id, (int, float)) and int(convert_id) == convert_id:
            convert_id = str(int(convert_id))
        else:
            return _err("VALIDATION_ERROR", "convert_id must be a string")
    if convert_id is not None:
        convert_id = convert_id.strip()
        if not convert_id:
            return _err("VALIDATION_ERROR", "convert_id must be a non-empty string")

    aux_list = [p.strip() for p in aux.split(",") if p.strip()] if isinstance(aux, str) and aux.strip() else []

    # ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")
    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key["id"]

    last_req = _parse_iso(key.get("last_request_at"))
    if last_req is None or _minute_bucket(last_req) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last_req is None or _day_bucket(last_req) != _day_bucket(now):
        key["requests_today"] = 0
    if last_req is None or _month_bucket(last_req) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_limit = key.get("requests_per_minute_limit", 0) or 0
    day_limit = key.get("requests_per_day_limit", 0) or 0
    credit_limit = key.get("monthly_credit_limit", 0) or 0
    credits_charged = 1

    request_params = {"start": start, "limit": limit, "sort": sort, "sort_dir": sort_dir, "type": type}
    if aux is not None: request_params["aux"] = aux
    if convert_id is not None: request_params["convert_id"] = convert_id

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": _new_id("cmc_req"),
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": int(credits_charged),
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if isinstance(rpm_limit, int) and rpm_limit > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_limit:
        log_row["error_code"] = "rate_limited"; log_row["error_message"] = "Per-minute request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if isinstance(day_limit, int) and day_limit > 0 and int(key.get("requests_today", 0) or 0) >= day_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Daily request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if isinstance(credit_limit, int) and credit_limit > 0 and (int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)) > credit_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Monthly credit limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # data: dex listings joined with market_data dex_listing_latest_row
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    dexes = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "dex" and a.get("status") != "deleted"]

    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    latest_by_dex = {}
    for row in mkt:
        if not isinstance(row, dict):
            continue
        if row.get("record_type") != "dex_listing_latest_row":
            continue
        if row.get("status") not in ("fresh", "stale"):
            continue
        if convert_id is not None and row.get("convert_upstream_id") != convert_id:
            continue
        dex_asset_id = row.get("primary_asset_id")
        if not isinstance(dex_asset_id, str):
            continue
        asof = _parse_iso(row.get("as_of"))
        if asof is None:
            continue
        prev = latest_by_dex.get(dex_asset_id)
        if prev is None or _parse_iso(prev.get("as_of")) < asof:
            latest_by_dex[dex_asset_id] = row

    out = []
    for a in dexes:
        if type != "all":
            md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
            t = md.get("type")
            if isinstance(t, str):
                if t.lower() != type:
                    continue
            else:
                tags = a.get("tags") if isinstance(a.get("tags"), list) else []
                if type not in [str(x).lower() for x in tags if isinstance(x, str)]:
                    continue

        row = {"id": a.get("upstream_id"), "name": a.get("name"), "slug": a.get("slug")}
        md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
        if aux_list:
            row["metadata"] = {k: md.get(k) for k in aux_list if k in md}

        md_row = latest_by_dex.get(a.get("id"))
        if isinstance(md_row, dict):
            row["metrics"] = md_row.get("numeric_fields")
            row["aux"] = md_row.get("aux_fields")
            row["as_of"] = md_row.get("as_of")
        out.append(row)

    # sorting
    def _num(x, path, default=0.0):
        cur = x
        for p in path:
            if not isinstance(cur, dict):
                return default
            cur = cur.get(p)
        if isinstance(cur, (int, float)):
            return float(cur)
        return default

    if sort == "name":
        out.sort(key=lambda r: ((r.get("name") or "").lower(), (r.get("id") or "")))
    elif sort == "volume_24h":
        out.sort(key=lambda r: _num(r, ["metrics", "volume_24h"], 0.0))
    elif sort == "market_share":
        out.sort(key=lambda r: _num(r, ["metrics", "market_share"], 0.0))
    elif sort == "num_markets":
        out.sort(key=lambda r: _num(r, ["metrics", "num_markets"], 0.0))

    if sort_dir == "desc":
        out.reverse()

    total = len(out)
    page = out[(start_i - 1):(start_i - 1 + limit_i)]
    resp = {
        "data": page,
        "pagination": {
            "start": start_i,
            "limit": limit_i,
            "total": total,
            "has_more": (start_i - 1 + limit_i) < total,
        },
        "status": {"timestamp": _iso(now), "error_code": None, "error_message": None},
    }

    log_row["duration_ms"] = int((time.time() - _t0) * 1000)
    logs.append(log_row); _save("request_logs.json", logs)
    return {"data": resp}

def dexNetworksList(start=None, limit=None, sort=None, sort_dir=None, aux=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "dexNetworksList"

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt.year, dt.month)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _parse_pos_int(v, field, default):
        if v is None:
            return default, None
        if isinstance(v, (int, float)) and int(v) == v:
            iv = int(v)
            if iv < 1:
                return None, _err("VALIDATION_ERROR", f"{field} must be >= 1 (1-based)")
            return iv, None
        if isinstance(v, str):
            s = v.strip()
            if not s.isdigit():
                return None, _err("VALIDATION_ERROR", f"{field} must be a string integer (1-based)")
            iv = int(s)
            if iv < 1:
                return None, _err("VALIDATION_ERROR", f"{field} must be >= 1 (1-based)")
            return iv, None
        return None, _err("VALIDATION_ERROR", f"{field} must be a string integer (1-based)")

    start_i, e = _parse_pos_int(start, "start", 1)
    if e: return e
    limit_i, e = _parse_pos_int(limit, "limit", 100)
    if e: return e
    if limit_i < 1 or limit_i > 5000:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 5000")

    if sort is None:
        sort = "id"
    if sort_dir is None:
        sort_dir = "asc"
    if sort not in ("id", "name"):
        return _err("VALIDATION_ERROR", "sort must be one of: id, name")
    if sort_dir not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_dir must be one of: asc, desc")
    if aux is not None and not isinstance(aux, str):
        return _err("VALIDATION_ERROR", "aux must be a string")
    aux_list = [p.strip() for p in aux.split(",") if p.strip()] if isinstance(aux, str) and aux.strip() else []

    # ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")
    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key["id"]

    last_req = _parse_iso(key.get("last_request_at"))
    if last_req is None or _minute_bucket(last_req) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last_req is None or _day_bucket(last_req) != _day_bucket(now):
        key["requests_today"] = 0
    if last_req is None or _month_bucket(last_req) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_limit = key.get("requests_per_minute_limit", 0) or 0
    day_limit = key.get("requests_per_day_limit", 0) or 0
    credit_limit = key.get("monthly_credit_limit", 0) or 0
    credits_charged = 1

    request_params = {}
    if start is not None: request_params["start"] = start
    if limit is not None: request_params["limit"] = limit
    if sort is not None: request_params["sort"] = sort
    if sort_dir is not None: request_params["sort_dir"] = sort_dir
    if aux is not None: request_params["aux"] = aux

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": _new_id("cmc_req"),
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": int(credits_charged),
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if isinstance(rpm_limit, int) and rpm_limit > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_limit:
        log_row["error_code"] = "rate_limited"; log_row["error_message"] = "Per-minute request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if isinstance(day_limit, int) and day_limit > 0 and int(key.get("requests_today", 0) or 0) >= day_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Daily request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if isinstance(credit_limit, int) and credit_limit > 0 and (int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)) > credit_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Monthly credit limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    nets = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "dex_network" and a.get("status") != "deleted"]

    if sort == "id":
        nets.sort(key=lambda r: (str(r.get("upstream_id") or ""), str(r.get("id") or "")))
    else:
        nets.sort(key=lambda r: ((r.get("name") or "").lower(), str(r.get("upstream_id") or "")))
    if sort_dir == "desc":
        nets.reverse()

    total = len(nets)
    page = nets[(start_i - 1):(start_i - 1 + limit_i)]

    out = []
    for a in page:
        md = a.get("metadata") if isinstance(a.get("metadata"), dict) else {}
        row = {"id": a.get("upstream_id"), "name": a.get("name"), "slug": a.get("slug")}
        if aux_list:
            row["metadata"] = {k: md.get(k) for k in aux_list if k in md}
        out.append(row)

    resp = {
        "data": out,
        "pagination": {"start": start_i, "limit": limit_i, "total": total, "has_more": (start_i - 1 + limit_i) < total},
        "status": {"timestamp": _iso(now), "error_code": None, "error_message": None},
    }

    log_row["duration_ms"] = int((time.time() - _t0) * 1000)
    logs.append(log_row); _save("request_logs.json", logs)
    return {"data": resp}

def dexSpotPairsLatest(network_id=None, network_slug=None, dex_id=None, dex_slug=None, base_asset_id=None, base_asset_symbol=None, base_asset_contract_address=None, base_asset_ucid=None, quote_asset_id=None, quote_asset_symbol=None, quote_asset_contract_address=None, quote_asset_ucid=None, scroll_id=None, limit=None, liquidity_min=None, liquidity_max=None, volume_24h_min=None, volume_24h_max=None, no_of_transactions_24h_min=None, no_of_transactions_24h_max=None, percent_change_24h_min=None, percent_change_24h_max=None, sort=None, sort_dir=None, aux=None, reverse_order=None, convert_id=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    tool_name = "dexSpotPairsLatest"
    allowed_keys = {
        "network_id", "network_slug", "dex_id", "dex_slug",
        "base_asset_id", "base_asset_symbol", "base_asset_contract_address", "base_asset_ucid",
        "quote_asset_id", "quote_asset_symbol", "quote_asset_contract_address", "quote_asset_ucid",
        "scroll_id", "limit",
        "liquidity_min", "liquidity_max", "volume_24h_min", "volume_24h_max",
        "no_of_transactions_24h_min", "no_of_transactions_24h_max",
        "percent_change_24h_min", "percent_change_24h_max",
        "sort", "sort_dir", "aux", "reverse_order", "convert_id"
    }
    request_params = {k: v for k, v in {
        "network_id": network_id, "network_slug": network_slug, "dex_id": dex_id, "dex_slug": dex_slug,
        "base_asset_id": base_asset_id, "base_asset_symbol": base_asset_symbol, "base_asset_contract_address": base_asset_contract_address, "base_asset_ucid": base_asset_ucid,
        "quote_asset_id": quote_asset_id, "quote_asset_symbol": quote_asset_symbol, "quote_asset_contract_address": quote_asset_contract_address, "quote_asset_ucid": quote_asset_ucid,
        "scroll_id": scroll_id, "limit": limit,
        "liquidity_min": liquidity_min, "liquidity_max": liquidity_max,
        "volume_24h_min": volume_24h_min, "volume_24h_max": volume_24h_max,
        "no_of_transactions_24h_min": no_of_transactions_24h_min, "no_of_transactions_24h_max": no_of_transactions_24h_max,
        "percent_change_24h_min": percent_change_24h_min, "percent_change_24h_max": percent_change_24h_max,
        "sort": sort, "sort_dir": sort_dir, "aux": aux, "reverse_order": reverse_order, "convert_id": convert_id
    }.items() if k in allowed_keys and v is not None}

    def _parse_int(s, field, minv=None, maxv=None):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string integer")
        try:
            v = int(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a string integer")
        if minv is not None and v < minv:
            return None, _err("VALIDATION_ERROR", f"{field} must be >= {minv}")
        if maxv is not None and v > maxv:
            return None, _err("VALIDATION_ERROR", f"{field} must be <= {maxv}")
        return v, None

    def _parse_float(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a string number")
        try:
            v = float(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a string number")
        return v, None

    lim, e = _parse_int(limit if limit is not None else "100", "limit", 1, 5000)
    if e:
        return e

    if sort is not None and sort not in (
        "name", "date_added", "price", "volume_24h", "percent_change_1h", "percent_change_24h",
        "liquidity", "fully_diluted_value", "no_of_transactions_24h"
    ):
        return _err("VALIDATION_ERROR", "Invalid sort", allowed=[
            "name", "date_added", "price", "volume_24h", "percent_change_1h", "percent_change_24h",
            "liquidity", "fully_diluted_value", "no_of_transactions_24h"
        ])

    if sort_dir is not None and sort_dir not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid sort_dir", allowed=["asc", "desc"])

    def _parse_boolish(s):
        if s is None:
            return False, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "reverse_order must be a string boolean")
        v = s.strip().lower()
        if v in ("1", "true", "t", "yes", "y", "on"):
            return True, None
        if v in ("0", "false", "f", "no", "n", "off", ""):
            return False, None
        return None, _err("VALIDATION_ERROR", "reverse_order must be a boolean string")

    rev, e = _parse_boolish(reverse_order)
    if e:
        return e

    liq_min, e = _parse_float(liquidity_min, "liquidity_min")
    if e:
        return e
    liq_max, e = _parse_float(liquidity_max, "liquidity_max")
    if e:
        return e
    vol_min, e = _parse_float(volume_24h_min, "volume_24h_min")
    if e:
        return e
    vol_max, e = _parse_float(volume_24h_max, "volume_24h_max")
    if e:
        return e
    tx_min, e = _parse_float(no_of_transactions_24h_min, "no_of_transactions_24h_min")
    if e:
        return e
    tx_max, e = _parse_float(no_of_transactions_24h_max, "no_of_transactions_24h_max")
    if e:
        return e
    pc24_min, e = _parse_float(percent_change_24h_min, "percent_change_24h_min")
    if e:
        return e
    pc24_max, e = _parse_float(percent_change_24h_max, "percent_change_24h_max")
    if e:
        return e

    # Ambient authentication & quota/rate enforcement
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    minute_bucket = now.strftime("%Y-%m-%dT%H:%MZ")
    day_bucket = now.strftime("%Y-%m-%d")
    month_bucket = now.strftime("%Y-%m")

    def _bucket_from_iso(iso):
        if not iso or not isinstance(iso, str):
            return None, None, None
        s = iso.replace("Z", "+00:00")
        try:
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            return dt.strftime("%Y-%m-%dT%H:%MZ"), dt.strftime("%Y-%m-%d"), dt.strftime("%Y-%m")
        except ValueError:
            return None, None, None

    credits_charged = 2  # heavier endpoint

    chosen = None
    for k in active_keys:
        last_min, last_day, last_month = _bucket_from_iso(k.get("last_request_at"))
        rpm_limit = k.get("requests_per_minute_limit", 0)
        rpd_limit = k.get("requests_per_day_limit", 0)
        mcred_limit = k.get("monthly_credit_limit", 0)
        rmin = k.get("requests_this_minute", 0) if isinstance(k.get("requests_this_minute"), int) else 0
        rday = k.get("requests_today", 0) if isinstance(k.get("requests_today"), int) else 0
        cmon = k.get("credits_month_to_date", 0) if isinstance(k.get("credits_month_to_date"), int) else 0
        if last_min != minute_bucket:
            rmin = 0
        if last_day != day_bucket:
            rday = 0
        if last_month != month_bucket:
            cmon = 0
        if isinstance(rpm_limit, int) and rpm_limit > 0 and rmin >= rpm_limit:
            continue
        if isinstance(rpd_limit, int) and rpd_limit > 0 and rday >= rpd_limit:
            continue
        if isinstance(mcred_limit, int) and mcred_limit > 0 and (cmon + credits_charged) > mcred_limit:
            continue
        chosen = (k, rmin, rday, cmon)
        break

    if not chosen:
        key_row = active_keys[0] if active_keys else None
        if key_row:
            log_id = "req_" + hashlib.sha256(f"{tool_name}|{now_iso}|{len(logs)}".encode("utf-8")).hexdigest()[:24]
            logs.append({
                "id": log_id,
                "api_key_id": key_row.get("id"),
                "tool_name": tool_name,
                "request_params": request_params,
                "cache_key": None,
                "cache_hit": False,
                "upstream_http_status": None,
                "credits_charged": 0,
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "error_code": "UNAUTHORIZED" if not active_keys else "RATE_LIMIT",
                "error_message": "No active API key available or all keys are rate/quota limited",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("request_logs.json", logs)
        return _err("UNAUTHORIZED" if not active_keys else "RATE_LIMIT", "Request not authorized or limited")

    key_row, eff_rmin, eff_rday, eff_cmon = chosen
    key_row["requests_this_minute"] = eff_rmin + 1
    key_row["requests_today"] = eff_rday + 1
    key_row["credits_month_to_date"] = eff_cmon + credits_charged
    key_row["last_request_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    directory = _load("asset_directory.json")
    if not isinstance(directory, list):
        directory = []
    market = _load("market_data.json")
    if not isinstance(market, list):
        market = []

    # Resolve selectors to asset_directory ids when possible
    def _find_one(entity_type, upstream_id=None, slug=None, symbol=None):
        for r in directory:
            if not isinstance(r, dict):
                continue
            if r.get("entity_type") != entity_type or r.get("status") == "deleted":
                continue
            if upstream_id is not None and str(r.get("upstream_id")) == str(upstream_id):
                return r
            if slug is not None and r.get("slug") and str(r.get("slug")) == str(slug):
                return r
            if symbol is not None and r.get("symbol") and str(r.get("symbol")).upper() == str(symbol).upper():
                return r
        return None

    network_row = _find_one("dex_network", upstream_id=network_id, slug=network_slug) if (network_id or network_slug) else None
    dex_row = _find_one("dex", upstream_id=dex_id, slug=dex_slug) if (dex_id or dex_slug) else None

    # Assets can be cryptocurrency/fiat; for DEX pairs we accept any entity_type but match by upstream_id/symbol and contract address in metadata.
    def _match_contract(r, addr):
        if not addr or not isinstance(addr, str):
            return False
        md = r.get("metadata") if isinstance(r.get("metadata"), dict) else {}
        addr_l = addr.strip().lower()
        plat = md.get("platform") if isinstance(md.get("platform"), dict) else {}
        ca = plat.get("contract_address")
        if isinstance(ca, str) and ca.strip().lower() == addr_l:
            return True
        cas = md.get("contract_addresses")
        if isinstance(cas, list):
            for x in cas:
                if isinstance(x, str) and x.strip().lower() == addr_l:
                    return True
                if isinstance(x, dict):
                    v = x.get("contract_address") or x.get("address")
                    if isinstance(v, str) and v.strip().lower() == addr_l:
                        return True
        return False

    def _find_asset(asset_id=None, symbol=None, contract=None, ucid=None):
        # asset_id treated as upstream_id selector
        for r in directory:
            if not isinstance(r, dict) or r.get("status") == "deleted":
                continue
            if asset_id is not None and str(r.get("upstream_id")) == str(asset_id):
                return r
        if symbol is not None:
            for r in directory:
                if not isinstance(r, dict) or r.get("status") == "deleted":
                    continue
                if r.get("symbol") and str(r.get("symbol")).upper() == str(symbol).upper():
                    return r
        if contract is not None:
            for r in directory:
                if not isinstance(r, dict) or r.get("status") == "deleted":
                    continue
                if _match_contract(r, contract):
                    return r
        if ucid is not None:
            # ucid treated as upstream_id too (CoinMarketCap "ucid")
            for r in directory:
                if not isinstance(r, dict) or r.get("status") == "deleted":
                    continue
                if str(r.get("upstream_id")) == str(ucid):
                    return r
        return None

    base_row = _find_asset(base_asset_id, base_asset_symbol, base_asset_contract_address, base_asset_ucid) if (base_asset_id or base_asset_symbol or base_asset_contract_address or base_asset_ucid) else None
    quote_row = _find_asset(quote_asset_id, quote_asset_symbol, quote_asset_contract_address, quote_asset_ucid) if (quote_asset_id or quote_asset_symbol or quote_asset_contract_address or quote_asset_ucid) else None

    # Filter market rows for dex_spot_pair_latest_row
    rows = [r for r in market if isinstance(r, dict) and r.get("record_type") == "dex_spot_pair_latest_row" and r.get("status") in ("fresh", "stale")]

    def _num(r, key):
        nf = r.get("numeric_fields") if isinstance(r.get("numeric_fields"), dict) else {}
        v = nf.get(key)
        if isinstance(v, (int, float)):
            return float(v)
        return None

    # Apply identifier filters. We interpret:
    # - primary_asset_id: dex id
    # - secondary_asset_id: network id
    # - aux_fields may contain base_asset_id/quote_asset_id upstream ids
    def _aux_get(r, k):
        af = r.get("aux_fields") if isinstance(r.get("aux_fields"), dict) else {}
        return af.get(k)

    if network_row:
        rows = [r for r in rows if r.get("secondary_asset_id") == network_row.get("id")]
    if dex_row:
        rows = [r for r in rows if r.get("primary_asset_id") == dex_row.get("id")]

    if base_row:
        bid = base_row.get("id")
        rows = [r for r in rows if _aux_get(r, "base_asset_id") == bid or _aux_get(r, "base_asset_upstream_id") == base_row.get("upstream_id")]
    if quote_row:
        qid = quote_row.get("id")
        rows = [r for r in rows if _aux_get(r, "quote_asset_id") == qid or _aux_get(r, "quote_asset_upstream_id") == quote_row.get("upstream_id")]

    # Range constraints
    def _apply_range(rows_in, field, minv, maxv):
        if minv is None and maxv is None:
            return rows_in
        out = []
        for r in rows_in:
            v = _num(r, field)
            if v is None:
                continue
            if minv is not None and v < minv:
                continue
            if maxv is not None and v > maxv:
                continue
            out.append(r)
        return out

    rows = _apply_range(rows, "liquidity", liq_min, liq_max)
    rows = _apply_range(rows, "volume_24h", vol_min, vol_max)
    rows = _apply_range(rows, "no_of_transactions_24h", tx_min, tx_max)
    rows = _apply_range(rows, "percent_change_24h", pc24_min, pc24_max)

    # Sorting
    s = sort or "volume_24h"
    sd = sort_dir or "desc"

    def _sort_key(r):
        if s == "name":
            return str(_aux_get(r, "pair_name") or _aux_get(r, "name") or "").lower()
        if s == "date_added":
            return str(_aux_get(r, "date_added") or r.get("created_at") or "")
        if s == "price":
            return _num(r, "price") if _num(r, "price") is not None else float("-inf")
        if s == "volume_24h":
            return _num(r, "volume_24h") if _num(r, "volume_24h") is not None else float("-inf")
        if s == "percent_change_1h":
            return _num(r, "percent_change_1h") if _num(r, "percent_change_1h") is not None else float("-inf")
        if s == "percent_change_24h":
            return _num(r, "percent_change_24h") if _num(r, "percent_change_24h") is not None else float("-inf")
        if s == "liquidity":
            return _num(r, "liquidity") if _num(r, "liquidity") is not None else float("-inf")
        if s == "fully_diluted_value":
            return _num(r, "fully_diluted_value") if _num(r, "fully_diluted_value") is not None else float("-inf")
        if s == "no_of_transactions_24h":
            return _num(r, "no_of_transactions_24h") if _num(r, "no_of_transactions_24h") is not None else float("-inf")
        return 0

    rows.sort(key=_sort_key, reverse=(sd == "desc"))
    if rev:
        rows.reverse()

    # Cursor paging: scroll_id encodes last seen (as_of|id)
    def _cursor_for(r):
        return f"{r.get('as_of','')}|{r.get('id','')}"

    if scroll_id is not None:
        if not isinstance(scroll_id, str):
            return _err("VALIDATION_ERROR", "scroll_id must be a string")
        # find first item after the cursor in current order
        idx = 0
        found = False
        for i, r in enumerate(rows):
            if _cursor_for(r) == scroll_id:
                idx = i + 1
                found = True
                break
        if found:
            rows = rows[idx:]
        else:
            # unknown cursor: treat as empty page
            rows = []

    page = rows[:lim]
    next_scroll = _cursor_for(page[-1]) if len(page) == lim else None

    aux_set = set()
    if isinstance(aux, str) and aux.strip():
        aux_set = {a.strip() for a in aux.split(",") if a.strip()}

    def _project_pair(r):
        af = r.get("aux_fields") if isinstance(r.get("aux_fields"), dict) else {}
        out = {
            "id": r.get("id"),
            "as_of": r.get("as_of"),
            "contract_address": r.get("contract_address"),
            "dex_id": dex_id or af.get("dex_upstream_id"),
            "network_id": network_id or af.get("network_upstream_id"),
            "name": af.get("pair_name") or af.get("name"),
            "quote": r.get("numeric_fields") if isinstance(r.get("numeric_fields"), dict) else {}
        }
        if convert_id is not None:
            out["convert_id"] = convert_id
        if aux_set:
            for k in ("base_asset_id", "quote_asset_id", "base_asset_symbol", "quote_asset_symbol", "url", "last_updated"):
                if k in aux_set and k in af:
                    out[k] = af.get(k)
            if "aux_fields" in aux_set:
                out["aux_fields"] = af
        return out

    data = [_project_pair(r) for r in page]

    log_id = "req_" + hashlib.sha256(f"{tool_name}|{now_iso}|{len(logs)}".encode("utf-8")).hexdigest()[:24]
    logs.append({
        "id": log_id,
        "api_key_id": key_row.get("id"),
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": 200,
        "credits_charged": credits_charged,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("request_logs.json", logs)

    return {
        "status": {"timestamp": now_iso, "error_code": 0, "error_message": None},
        "data": data,
        "pagination": {
            "limit": lim,
            "scroll_id": scroll_id,
            "next_scroll_id": next_scroll,
            "count": len(data),
            "has_more": next_scroll is not None
        }
    }

def dexPairsQuotesLatest(contract_address=None, network_id=None, network_slug=None, aux=None, convert_id=None, skip_invalid=None, reverse_order=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "dexPairsQuotesLatest"

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt.year, dt.month)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _boolish(v, default=False):
        if v is None:
            return default, None
        if isinstance(v, bool):
            return v, None
        if isinstance(v, (int, float)) and int(v) == v:
            return bool(int(v)), None
        if isinstance(v, str):
            s = v.strip().lower()
            if s in ("1", "true", "t", "yes", "y", "on"):
                return True, None
            if s in ("0", "false", "f", "no", "n", "off", ""):
                return False, None
            # tolerate garbage by treating non-empty as True for these historically-miswired params
            return True, None
        return default, None

    # Validate required contract_address
    if not isinstance(contract_address, str) or not contract_address.strip():
        return _err("VALIDATION_ERROR", "contract_address is required and must be a non-empty string")
    contract_address = contract_address.strip()

    # Network selector: accept ambiguous inputs by preferring network_id if present (audit showed both sent)
    if network_id is None and network_slug is None:
        return _err("VALIDATION_ERROR", "Provide network_id or network_slug")
    if network_id is not None and not isinstance(network_id, str):
        if isinstance(network_id, (int, float)) and int(network_id) == network_id:
            network_id = str(int(network_id))
        else:
            return _err("VALIDATION_ERROR", "network_id must be a string")
    if network_slug is not None and not isinstance(network_slug, str):
        return _err("VALIDATION_ERROR", "network_slug must be a string")
    if network_id is not None:
        network_id = network_id.strip()
    if network_slug is not None:
        network_slug = network_slug.strip().lower()

    if aux is not None and not isinstance(aux, str):
        return _err("VALIDATION_ERROR", "aux must be a string")
    aux_list = [p.strip() for p in aux.split(",") if p.strip()] if isinstance(aux, str) and aux.strip() else []

    if convert_id is not None and not isinstance(convert_id, str):
        if isinstance(convert_id, (int, float)) and int(convert_id) == convert_id:
            convert_id = str(int(convert_id))
        else:
            return _err("VALIDATION_ERROR", "convert_id must be a string")
    if convert_id is not None:
        convert_id = convert_id.strip()
        if not convert_id:
            return _err("VALIDATION_ERROR", "convert_id must be a non-empty string")

    skip, _ = _boolish(skip_invalid, default=False)
    rev, _ = _boolish(reverse_order, default=False)

    # ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")
    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key["id"]

    last_req = _parse_iso(key.get("last_request_at"))
    if last_req is None or _minute_bucket(last_req) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last_req is None or _day_bucket(last_req) != _day_bucket(now):
        key["requests_today"] = 0
    if last_req is None or _month_bucket(last_req) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_limit = key.get("requests_per_minute_limit", 0) or 0
    day_limit = key.get("requests_per_day_limit", 0) or 0
    credit_limit = key.get("monthly_credit_limit", 0) or 0
    credits_charged = 1

    request_params = {"contract_address": contract_address}
    if network_id is not None: request_params["network_id"] = network_id
    if network_slug is not None: request_params["network_slug"] = network_slug
    if aux is not None: request_params["aux"] = aux
    if convert_id is not None: request_params["convert_id"] = convert_id
    if skip_invalid is not None: request_params["skip_invalid"] = skip_invalid
    if reverse_order is not None: request_params["reverse_order"] = reverse_order

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": _new_id("cmc_req"),
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": int(credits_charged),
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if isinstance(rpm_limit, int) and rpm_limit > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_limit:
        log_row["error_code"] = "rate_limited"; log_row["error_message"] = "Per-minute request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if isinstance(day_limit, int) and day_limit > 0 and int(key.get("requests_today", 0) or 0) >= day_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Daily request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if isinstance(credit_limit, int) and credit_limit > 0 and (int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)) > credit_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Monthly credit limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    # resolve network asset_directory row
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    nets = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "dex_network" and a.get("status") != "deleted"]
    network_row = None
    if network_id:
        for a in nets:
            if a.get("upstream_id") == network_id:
                network_row = a
                break
    if network_row is None and network_slug:
        for a in nets:
            if isinstance(a.get("slug"), str) and a.get("slug").lower() == network_slug:
                network_row = a
                break
    if network_row is None:
        if skip:
            log_row["duration_ms"] = int((time.time() - _t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return {"data": {"data": [], "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}}}
        log_row["error_code"] = "not_found"; log_row["error_message"] = "Network not found"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Network not found", network_id=network_id, network_slug=network_slug)

    # find latest pair quote by contract + network
    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []
    best = None
    best_asof = None
    for row in mkt:
        if not isinstance(row, dict):
            continue
        if row.get("record_type") != "dex_pair_quote_latest":
            continue
        if row.get("contract_address") != contract_address:
            continue
        if row.get("secondary_asset_id") != network_row.get("id"):
            continue
        if convert_id is not None and row.get("convert_upstream_id") != convert_id:
            continue
        if row.get("status") not in ("fresh", "stale"):
            continue
        asof = _parse_iso(row.get("as_of"))
        if asof is None:
            continue
        if best is None or asof > best_asof:
            best = row
            best_asof = asof

    if best is None:
        if skip:
            resp = {"data": [], "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}}
            log_row["duration_ms"] = int((time.time() - _t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return {"data": resp}
        log_row["error_code"] = "not_found"; log_row["error_message"] = "Pair not found"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Pair not found for contract_address on network")

    resp_item = {
        "contract_address": contract_address,
        "network": {"id": network_row.get("upstream_id"), "slug": network_row.get("slug"), "name": network_row.get("name")},
        "as_of": best.get("as_of"),
        "numeric": best.get("numeric_fields"),
        "aux": best.get("aux_fields"),
    }
    if aux_list:
        resp_item["requested_aux"] = aux_list

    resp = {"data": [resp_item] if not rev else [resp_item], "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}}

    log_row["duration_ms"] = int((time.time() - _t0) * 1000)
    logs.append(log_row); _save("request_logs.json", logs)
    return {"data": resp}

