    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    def _split_csv(v):
        if v is None:
            return []
        if not isinstance(v, str):
            return None
        parts = [p.strip() for p in v.split(",")]
        return [p for p in parts if p]

    def _truthy(v):
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return v != 0
        if isinstance(v, str):
            s = v.strip().lower()
            if s in ("1", "true", "t", "yes", "y", "on"):
                return True
            if s in ("0", "false", "f", "no", "n", "off", ""):
                return False
            # any non-empty string treat as truthy (relaxed)
            return True
        return bool(v)

    # validate
    request_params = {}
    if contract_address is None or not isinstance(contract_address, str) or not contract_address.strip():
        return _err("VALIDATION_ERROR", "contract_address is required and must be a non-empty string")
    request_params["contract_address"] = contract_address.strip()

    if network_id is not None:
        # schema says string; accept ints by coercing to str
        if isinstance(network_id, (int, float)) and not isinstance(network_id, bool):
            network_id = str(int(network_id))
        if not isinstance(network_id, str) or not network_id.strip():
            return _err("VALIDATION_ERROR", "network_id must be a non-empty string when provided")
        request_params["network_id"] = network_id.strip()

    if network_slug is not None:
        if not isinstance(network_slug, str) or not network_slug.strip():
            return _err("VALIDATION_ERROR", "network_slug must be a non-empty string when provided")
        request_params["network_slug"] = network_slug.strip()

    if network_id is None and network_slug is None:
        return _err("VALIDATION_ERROR", "Either network_id or network_slug must be provided")

    if aux is not None:
        if not isinstance(aux, str):
            return _err("VALIDATION_ERROR", "aux must be a string when provided")
        request_params["aux"] = aux
    if convert_id is not None:
        if isinstance(convert_id, (int, float)) and not isinstance(convert_id, bool):
            convert_id = str(int(convert_id))
        if not isinstance(convert_id, str) or not convert_id.strip():
            return _err("VALIDATION_ERROR", "convert_id must be a non-empty string when provided")
        request_params["convert_id"] = convert_id.strip()
    if skip_invalid is not None:
        request_params["skip_invalid"] = skip_invalid
    if reverse_order is not None:
        request_params["reverse_order"] = reverse_order

    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    credits = 1
    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    # cache lookup
    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((time.time() - t0) * 1000))
                        return c["response_body"]
                break

    aux_set = _split_csv(aux)
    if aux_set is None:
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message="aux must be a comma-separated string")
        return _err("VALIDATION_ERROR", "aux must be a comma-separated string")

    allowed_aux = {"urls", "logo", "description", "fee", "tx_hash", "trade_id", "maker", "taker"}
    for a in aux_set:
        if a not in allowed_aux:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message=f"Invalid aux value: {a}")
            return _err("VALIDATION_ERROR", f"Invalid aux value: {a}")

    # resolve network row
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    networks = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "dex_network" and a.get("status") != "deleted"]

    resolved_network = None
    if network_id is not None:
        for n in networks:
            if str(n.get("upstream_id")) == str(network_id).strip():
                resolved_network = n
                break
    if resolved_network is None and network_slug is not None:
        for n in networks:
            if str(n.get("slug") or "").strip().lower() == str(network_slug).strip().lower():
                resolved_network = n
                break

    if resolved_network is None:
        # network not found: honor skip_invalid-like behavior? spec says for pair tools; treat as validation unless skip_invalid truthy -> empty
        if _truthy(skip_invalid):
            qerr = _enforce_and_increment(api_key_row, credits)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            resp = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": []}
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))
            return resp
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message="Network selector did not resolve to a single network")
        return _err("VALIDATION_ERROR", "Network selector did not resolve to a single network")

    # Find trades in market_data
    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    conv = str(convert_id).strip() if convert_id is not None else None

    candidates = []
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "dex_pair_trade":
            continue
        if r.get("status") in ("deleted",):
            continue
        if str(r.get("contract_address") or "") != contract_address.strip():
            continue
        # network match: prefer secondary_asset_id
        if r.get("secondary_asset_id") and r.get("secondary_asset_id") != resolved_network.get("id"):
            continue
        if r.get("secondary_asset_id") is None:
            # if no network FK stored, accept it
            pass
        if conv is not None and str(r.get("convert_upstream_id") or "") != conv:
            continue
        candidates.append(r)

    if not candidates:
        if _truthy(skip_invalid):
            qerr = _enforce_and_increment(api_key_row, credits)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            resp = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": []}
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))
            return resp
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message="Pair not found for given contract_address and network")
        return _err("NOT_FOUND", "Pair not found for given contract_address and network")

    # Newest trades: sort by as_of desc, then id desc
    candidates.sort(key=lambda r: (str(r.get("as_of") or ""), str(r.get("id") or "")), reverse=True)
    candidates = candidates[:100]

    if _truthy(reverse_order):
        candidates = list(reversed(candidates))

    def _project_trade(r):
        out = {
            "id": r.get("id"),
            "contract_address": r.get("contract_address"),
            "network": {"id": resolved_network.get("id"), "upstream_id": resolved_network.get("upstream_id"), "slug": resolved_network.get("slug"), "name": resolved_network.get("name")},
            "as_of": r.get("as_of"),
            "numeric": r.get("numeric_fields", {}),
        }
        auxf = r.get("aux_fields", {}) if isinstance(r.get("aux_fields"), dict) else {}
        if aux_set:
            for k in aux_set:
                if k in auxf:
                    out.setdefault("aux", {})[k] = auxf.get(k)
        else:
            out["aux"] = auxf
        return out

    response = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": [_project_trade(r) for r in candidates]}

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr
    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))

    # cache write-through short TTL
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(seconds=30)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def exchangeAssets(id=None, slug=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "exchangeAssets"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    # validate selectors
    request_params = {}
    if id is not None:
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string when provided")
        request_params["id"] = id.strip()
    if slug is not None:
        if not isinstance(slug, str) or not slug.strip():
            return _err("VALIDATION_ERROR", "slug must be a non-empty string when provided")
        request_params["slug"] = slug.strip()

    if id is None and slug is None:
        return _err("VALIDATION_ERROR", "Either id or slug must be provided")

    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    credits = 1
    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((time.time() - t0) * 1000))
                        return c["response_body"]
                break

    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    exchanges = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "exchange" and a.get("status") != "deleted"]

    resolved = None
    if id is not None:
        # exchangeAssets id is upstream_id (not api key id)
        for e in exchanges:
            if str(e.get("upstream_id")) == id.strip():
                resolved = e
                break
    if resolved is None and slug is not None:
        for e in exchanges:
            if str(e.get("slug") or "").lower() == slug.strip().lower():
                resolved = e
                break

    if resolved is None:
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message="Exchange not found")
        return _err("NOT_FOUND", "Exchange not found")

    # holdings in market_data.record_type='exchange_asset_holding'
    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []
    holdings = [r for r in mkt if isinstance(r, dict) and r.get("record_type") == "exchange_asset_holding" and r.get("status") != "deleted" and r.get("primary_asset_id") == resolved.get("id")]
    holdings.sort(key=lambda r: (str(r.get("as_of") or ""), str(r.get("id") or "")), reverse=True)
    latest_as_of = _parse_iso(holdings[0].get("as_of")) if holdings else None
    if latest_as_of:
        holdings = [r for r in holdings if _parse_iso(r.get("as_of")) == latest_as_of]
    holdings = holdings[:5000]

    # enrich with asset_directory for secondary_asset_id where possible
    by_id = {a.get("id"): a for a in assets if isinstance(a, dict) and a.get("id")}
    out_holdings = []
    for h in holdings:
        token = by_id.get(h.get("secondary_asset_id")) if h.get("secondary_asset_id") else None
        out_holdings.append({
            "as_of": h.get("as_of"),
            "asset": ({
                "id": token.get("id"),
                "entity_type": token.get("entity_type"),
                "upstream_id": token.get("upstream_id"),
                "slug": token.get("slug"),
                "symbol": token.get("symbol"),
                "name": token.get("name"),
            } if isinstance(token, dict) else None),
            "numeric": h.get("numeric_fields", {}),
            "aux": h.get("aux_fields", {}),
        })

    response = {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None},
        "data": {
            "exchange": {
                "id": resolved.get("id"),
                "upstream_id": resolved.get("upstream_id"),
                "slug": resolved.get("slug"),
                "name": resolved.get("name"),
                "listing_status": resolved.get("listing_status"),
                "status": resolved.get("status"),
                "last_synced_at": resolved.get("last_synced_at"),
            },
            "assets": out_holdings,
        }
    }

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr
    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))

    # cache write-through
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(minutes=5)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def exchangeInfo(id=None, slug=None, aux=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "exchangeInfo"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    def _split_csv(v):
        if v is None:
            return []
        if not isinstance(v, str):
            return None
        parts = [p.strip() for p in v.split(",")]
        return [p for p in parts if p]

    # validate
    request_params = {}
    if id is not None:
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string when provided")
        request_params["id"] = id.strip()
    if slug is not None:
        if not isinstance(slug, str) or not slug.strip():
            return _err("VALIDATION_ERROR", "slug must be a non-empty string when provided")
        request_params["slug"] = slug.strip()
    if aux is not None:
        if not isinstance(aux, str):
            return _err("VALIDATION_ERROR", "aux must be a string when provided")
        request_params["aux"] = aux

    if id is None and slug is None:
        return _err("VALIDATION_ERROR", "Either id or slug must be provided")

    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    credits = 1
    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((time.time() - t0) * 1000))
                        return c["response_body"]
                break

    aux_set = _split_csv(aux)
    if aux_set is None:
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message="aux must be a comma-separated string")
        return _err("VALIDATION_ERROR", "aux must be a comma-separated string")

    allowed_aux = {"urls", "logo", "description", "notice", "fee", "country", "fiats", "tags", "maker_fee", "taker_fee"}
    for a in aux_set:
        if a not in allowed_aux:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 400, 0, int((time.time() - t0) * 1000), error_code="validation_error", error_message=f"Invalid aux value: {a}")
            return _err("VALIDATION_ERROR", f"Invalid aux value: {a}")

    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    exchanges = [a for a in assets if isinstance(a, dict) and a.get("entity_type") == "exchange" and a.get("status") != "deleted"]

    resolved = []
    if id is not None:
        rid = id.strip()
        resolved = [e for e in exchanges if str(e.get("upstream_id")) == rid]
        if not resolved:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message=f"Exchange id not found: {rid}")
            return _err("NOT_FOUND", f"Exchange id not found: {rid}")
    if slug is not None:
        rslug = slug.strip().lower()
        m = [e for e in exchanges if str(e.get("slug") or "").lower() == rslug]
        if not m:
            qerr = _enforce_and_increment(api_key_row, 0)
            if qerr:
                _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                return qerr
            _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message=f"Exchange slug not found: {slug.strip()}")
            return _err("NOT_FOUND", f"Exchange slug not found: {slug.strip()}")
        if resolved:
            # both provided; must refer to same exchange
            if all(x.get("id") != m[0].get("id") for x in resolved):
                qerr = _enforce_and_increment(api_key_row, 0)
                if qerr:
                    _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                    return qerr
                _append_log(api_key_row.get("id"), request_params, cache_key, False, 409, 0, int((time.time() - t0) * 1000), error_code="conflict", error_message="id and slug refer to different exchanges")
                return _err("CONFLICT", "id and slug refer to different exchanges")
        resolved = m

    def _project(e):
        md = e.get("metadata") if isinstance(e.get("metadata"), dict) else {}
        out = {
            "id": e.get("id"),
            "upstream_id": e.get("upstream_id"),
            "slug": e.get("slug"),
            "name": e.get("name"),
            "listing_status": e.get("listing_status"),
            "status": e.get("status"),
            "last_synced_at": e.get("last_synced_at"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        }
        if not aux_set:
            return out
        if "urls" in aux_set:
            out["urls"] = md.get("urls")
        if "logo" in aux_set:
            out["logo"] = md.get("logo")
        if "description" in aux_set:
            out["description"] = md.get("description")
        if "notice" in aux_set:
            out["notice"] = md.get("notice")
        if "fee" in aux_set:
            out["fee"] = md.get("fee")
        if "country" in aux_set:
            out["country"] = md.get("country")
        if "fiats" in aux_set:
            out["fiats"] = md.get("fiats")
        if "tags" in aux_set:
            out["tags"] = e.get("tags", [])
        if "maker_fee" in aux_set:
            out["maker_fee"] = md.get("maker_fee")
        if "taker_fee" in aux_set:
            out["taker_fee"] = md.get("taker_fee")
        return out

    response = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": [_project(e) for e in resolved]}

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr
    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))

    # cache write-through for metadata
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(hours=6)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def exchangeMap(listing_status=None, slug=None, start=None, limit=None, sort=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate params
    if listing_status is not None and not isinstance(listing_status, str):
        return _err("VALIDATION_ERROR", "listing_status must be a string")
    if listing_status is not None and listing_status not in ("active", "inactive", "untracked"):
        return _err("VALIDATION_ERROR", "Unsupported listing_status", allowed=["active", "inactive", "untracked"])

    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string")
    if slug is not None:
        s = slug.strip()
        # "malformed" slug: enforce simple CMC-ish slug charset
        if not s or len(s) > 128 or not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", s):
            return _err("VALIDATION_ERROR", "slug is malformed")
        slug = s

    if start is None:
        start = 1
    if limit is None:
        limit = 100

    if not isinstance(start, (int, float)) or int(start) != start:
        return _err("VALIDATION_ERROR", "start must be an integer")
    if not isinstance(limit, (int, float)) or int(limit) != limit:
        return _err("VALIDATION_ERROR", "limit must be an integer")
    start = int(start)
    limit = int(limit)
    if start < 1 or start > 1000000:
        return _err("VALIDATION_ERROR", "start out of range")
    if limit < 1 or limit > 5000:
        return _err("VALIDATION_ERROR", "limit out of range")

    if sort is not None and not isinstance(sort, str):
        return _err("VALIDATION_ERROR", "sort must be a string")
    # Allowed sorts for this service: upstream_id or name
    if sort is None:
        sort = "upstream_id"
    if sort not in ("upstream_id", "name"):
        return _err("VALIDATION_ERROR", "Unsupported sort", allowed=["upstream_id", "name"])

    # Resolve an active API key (ambient auth)
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # still must log the request; but cannot due to missing api_key_id; vendor would reject unauthorized
        return _err("UNAUTHORIZED", "No active API key available")

    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key.get("id")
    if not api_key_id:
        return _err("UNAUTHORIZED", "No active API key available")

    request_logs = _load("request_logs.json")

    # Throttling windows (minute/day/month boundaries)
    def _parse_dt(v):
        if not v:
            return None
        try:
            if isinstance(v, str):
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None
        return None

    last_req = _parse_dt(key.get("last_request_at"))
    # Reset minute counter at minute boundary
    if last_req is None or (last_req.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0) != now.replace(second=0, microsecond=0)):
        key["requests_this_minute"] = 0
    # Reset daily counter at UTC day boundary
    if last_req is None or (last_req.astimezone(datetime.timezone.utc).date() != now.date()):
        key["requests_today"] = 0
    # Reset monthly credits at UTC month boundary
    if last_req is None or (last_req.astimezone(datetime.timezone.utc).year != now.year or last_req.astimezone(datetime.timezone.utc).month != now.month):
        key["credits_month_to_date"] = 0

    # Enforce rate limits (credits charged for this read-only tool: 1)
    credits_charged = 1
    rpm_limit = int(key.get("requests_per_minute_limit") or 0)
    rpd_limit = int(key.get("requests_per_day_limit") or 0)
    mcred_limit = int(key.get("monthly_credit_limit") or 0)

    if rpm_limit > 0 and int(key.get("requests_this_minute") or 0) >= rpm_limit:
        # log denied request
        log_id = "req_" + hashlib.sha256(f"{api_key_id}|exchangeMap|{now_iso}|{len(request_logs)}".encode("utf-8")).hexdigest()[:24]
        request_logs.append({
            "id": log_id,
            "api_key_id": api_key_id,
            "tool_name": "exchangeMap",
            "request_params": {"listing_status": listing_status, "slug": slug, "start": start, "limit": limit, "sort": sort},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "rate_limit",
            "error_message": "requests_per_minute_limit exceeded",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")

    if rpd_limit > 0 and int(key.get("requests_today") or 0) >= rpd_limit:
        log_id = "req_" + hashlib.sha256(f"{api_key_id}|exchangeMap|{now_iso}|{len(request_logs)}".encode("utf-8")).hexdigest()[:24]
        request_logs.append({
            "id": log_id,
            "api_key_id": api_key_id,
            "tool_name": "exchangeMap",
            "request_params": {"listing_status": listing_status, "slug": slug, "start": start, "limit": limit, "sort": sort},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": "requests_per_day_limit exceeded",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    if mcred_limit > 0 and (int(key.get("credits_month_to_date") or 0) + credits_charged) > mcred_limit:
        log_id = "req_" + hashlib.sha256(f"{api_key_id}|exchangeMap|{now_iso}|{len(request_logs)}".encode("utf-8")).hexdigest()[:24]
        request_logs.append({
            "id": log_id,
            "api_key_id": api_key_id,
            "tool_name": "exchangeMap",
            "request_params": {"listing_status": listing_status, "slug": slug, "start": start, "limit": limit, "sort": sort},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", request_logs)
        key["last_request_at"] = now_iso
        key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    # Main read
    directory = _load("asset_directory.json")
    rows = [r for r in directory if isinstance(r, dict) and r.get("entity_type") == "exchange" and r.get("status") != "deleted"]

    if listing_status is not None:
        rows = [r for r in rows if r.get("listing_status") == listing_status]
    if slug is not None:
        rows = [r for r in rows if (r.get("slug") or "").lower() == slug.lower()]

    # Sort deterministic
    if sort == "upstream_id":
        rows.sort(key=lambda r: (str(r.get("upstream_id") or ""), str(r.get("id") or "")))
    else:
        rows.sort(key=lambda r: (str(r.get("name") or "").lower(), str(r.get("upstream_id") or ""), str(r.get("id") or "")))

    total = len(rows)
    offset = start - 1
    page = rows[offset: offset + limit]

    # Update counters and log
    key["requests_this_minute"] = int(key.get("requests_this_minute") or 0) + 1
    key["requests_today"] = int(key.get("requests_today") or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date") or 0) + credits_charged
    key["last_request_at"] = now_iso
    key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    log_id = "req_" + hashlib.sha256(f"{api_key_id}|exchangeMap|{now_iso}|{len(request_logs)}".encode("utf-8")).hexdigest()[:24]
    request_logs.append({
        "id": log_id,
        "api_key_id": api_key_id,
        "tool_name": "exchangeMap",
        "request_params": {"listing_status": listing_status, "slug": slug, "start": start, "limit": limit, "sort": sort},
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": 200,
        "credits_charged": credits_charged,
        "duration_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("request_logs.json", request_logs)

    has_more = (offset + limit) < total
    return {
        "data": page,
        "status": {"timestamp": now_iso, "error_code": None, "error_message": None},
        "pagination": {
            "total": total,
            "start": start,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": (start + limit) if has_more else None
        }
    }

def globalMetricsLatest(convert=None, convert_id=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "globalMetricsLatest"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _normalize_convert_symbol(v):
        if v is None:
            return None, None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", "convert must be a string")
        s = v.strip()
        if s == "":
            return None, None
        return s.upper(), None

    def _normalize_convert_id(v):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", "convert_id must be a string")
        if isinstance(v, (int, float)):
            if isinstance(v, float) and v != int(v):
                return None, _err("VALIDATION_ERROR", "convert_id must be an integer-like value")
            return str(int(v)), None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", "convert_id must be a string")
        s = v.strip()
        if s == "":
            return None, None
        return s, None

    def _resolve_ambient_key(api_keys_rows):
        active = [r for r in api_keys_rows if isinstance(r, dict) and r.get("status") == "active" and r.get("id")]
        if not active:
            return None
        def _k(r):
            return (r.get("last_request_at") or "", r.get("updated_at") or "", r.get("created_at") or "")
        return sorted(active, key=_k, reverse=True)[0]

    def _reset_windows_if_needed(key_row):
        last = _parse_iso(key_row.get("last_request_at"))
        if last is None:
            return
        if last.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0) != now.replace(second=0, microsecond=0):
            key_row["requests_this_minute"] = 0
        if last.astimezone(datetime.timezone.utc).date() != now.date():
            key_row["requests_today"] = 0
        if (last.year, last.month) != (now.year, now.month):
            key_row["credits_month_to_date"] = 0

    def _check_and_consume(api_keys_rows, key_row, credits):
        _reset_windows_if_needed(key_row)
        rpm = int(key_row.get("requests_per_minute_limit", 0) or 0)
        rpd = int(key_row.get("requests_per_day_limit", 0) or 0)
        mcl = int(key_row.get("monthly_credit_limit", 0) or 0)
        rtmin = int(key_row.get("requests_this_minute", 0) or 0)
        rtday = int(key_row.get("requests_today", 0) or 0)
        cmt = int(key_row.get("credits_month_to_date", 0) or 0)
        if rpm > 0 and rtmin >= rpm:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded")
        if rpd > 0 and rtday >= rpd:
            return _err("QUOTA_EXCEEDED", "Per-day request limit exceeded")
        if mcl > 0 and (cmt + int(credits)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit limit exceeded")
        key_row["requests_this_minute"] = rtmin + 1
        key_row["requests_today"] = rtday + 1
        key_row["credits_month_to_date"] = cmt + int(credits)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        return None

    def _append_log(logs_rows, api_key_id, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs_rows.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged),
            "duration_ms": int(duration_ms),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })

    conv, e = _normalize_convert_symbol(convert)
    if e:
        return e
    conv_id, e = _normalize_convert_id(convert_id)
    if e:
        return e

    request_params = {}
    if conv is not None:
        request_params["convert"] = conv
    if conv_id is not None:
        request_params["convert_id"] = conv_id

    api_keys = _load("api_keys.json")
    key_row = _resolve_ambient_key(api_keys)
    cache_key = f"{tool_name}:{_stable_fingerprint(tool_name, request_params)}"
    credits = 1

    if not key_row:
        logs = _load("request_logs.json")
        _append_log(logs, "(none)", request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "unauthorized", "No active API key available")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available")
    if key_row.get("status") != "active":
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "unauthorized", "API key not active")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key not active")

    limit_err = _check_and_consume(api_keys, key_row, credits)
    if limit_err:
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "rate_limited" if limit_err["error"]["code"] == "RATE_LIMIT" else "quota_exceeded",
                    limit_err["error"]["message"][:200])
        _save("request_logs.json", logs)
        _save("api_keys.json", api_keys)
        return limit_err

    mkt = _load("market_data.json")
    candidates = []
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "global_metrics_latest":
            continue
        if r.get("status") == "deleted":
            continue
        # conversion matching: if requested, require row match; otherwise accept any and prefer unconverted
        if conv is not None and (r.get("convert_symbol") or "").upper() != conv:
            continue
        if conv_id is not None and str(r.get("convert_upstream_id") or "") != conv_id:
            continue
        candidates.append(r)

    if not candidates and (conv is not None or conv_id is not None):
        # relaxed fallback: if convert requested but no exact match exists, return latest available (usually USD/base)
        candidates = [r for r in mkt if isinstance(r, dict) and r.get("record_type") == "global_metrics_latest" and r.get("status") != "deleted"]

    if not candidates:
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, 404, credits, int((time.time() - t0) * 1000),
                    "not_found", "No global metrics cached"[:200])
        _save("request_logs.json", logs)
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", "No global metrics cached")

    candidates.sort(key=lambda r: (_parse_iso(r.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    row = candidates[0]

    response = {
        "data": {
            "as_of": row.get("as_of"),
            "convert": row.get("convert_symbol"),
            "convert_id": row.get("convert_upstream_id"),
            "numeric_fields": row.get("numeric_fields") if isinstance(row.get("numeric_fields"), dict) else {},
            "aux_fields": row.get("aux_fields") if isinstance(row.get("aux_fields"), dict) else {},
        }
    }

    logs = _load("request_logs.json")
    _append_log(logs, key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))
    _save("request_logs.json", logs)
    _save("api_keys.json", api_keys)
    return response

def cmc100IndexHistorical(time_start=None, time_end=None, count=None, interval=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "cmc100IndexHistorical"

    def _iso(dt):
        if isinstance(dt, str): return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_time(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a non-empty string")
        v = s.strip()
        if re.fullmatch(r"\d{10,13}", v):
            try:
                n = int(v)
                if len(v) == 13:
                    dt = datetime.datetime.fromtimestamp(n / 1000.0, tz=datetime.timezone.utc)
                else:
                    dt = datetime.datetime.fromtimestamp(n, tz=datetime.timezone.utc)
                return dt, None
            except ValueError:
                return None, _err("VALIDATION_ERROR", f"{field} is malformed")
        vv = v.replace("Z", "+00:00")
        try:
            dt = datetime.datetime.fromisoformat(vv)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is malformed")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _minute_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.astimezone(datetime.timezone.utc).date()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return (dt.year, dt.month)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    if interval is None:
        interval = "daily"
    if not isinstance(interval, str) or interval not in ("5m", "15m", "daily"):
        return _err("VALIDATION_ERROR", "interval must be one of the supported values", allowed=["5m", "15m", "daily"])

    ts, e = _parse_time(time_start, "time_start")
    if e: return e
    te, e = _parse_time(time_end, "time_end")
    if e: return e
    if ts and te and ts > te:
        return _err("VALIDATION_ERROR", "time_start must be <= time_end")

    cnt = None
    if count is not None:
        if isinstance(count, (int, float)) and int(count) == count:
            cnt = int(count)
        elif isinstance(count, str) and count.strip().isdigit():
            cnt = int(count.strip())
        else:
            return _err("VALIDATION_ERROR", "count must be an integer")
        if cnt < 1 or cnt > 10000:
            return _err("VALIDATION_ERROR", "count must be between 1 and 10000")

    # ambient auth + quotas
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available")
    key = max(active_keys, key=lambda r: (r.get("last_request_at") or "", r.get("created_at") or ""))
    api_key_id = key["id"]

    # reset windows based on key's last_request_at
    last_req = None
    if isinstance(key.get("last_request_at"), str):
        try:
            last_req = datetime.datetime.fromisoformat(key["last_request_at"].replace("Z", "+00:00"))
            if last_req.tzinfo is None:
                last_req = last_req.replace(tzinfo=datetime.timezone.utc)
            last_req = last_req.astimezone(datetime.timezone.utc)
        except ValueError:
            last_req = None

    if last_req is None or _minute_bucket(last_req) != _minute_bucket(now):
        key["requests_this_minute"] = 0
    if last_req is None or _day_bucket(last_req) != _day_bucket(now):
        key["requests_today"] = 0
    if last_req is None or _month_bucket(last_req) != _month_bucket(now):
        key["credits_month_to_date"] = 0

    rpm_limit = key.get("requests_per_minute_limit", 0) or 0
    day_limit = key.get("requests_per_day_limit", 0) or 0
    credit_limit = key.get("monthly_credit_limit", 0) or 0
    credits_charged = 1

    request_params = {}
    if time_start is not None: request_params["time_start"] = time_start
    if time_end is not None: request_params["time_end"] = time_end
    if count is not None: request_params["count"] = count
    if interval is not None: request_params["interval"] = interval

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": _new_id("cmc_req"),
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "request_params": request_params,
        "cache_key": None,
        "cache_hit": False,
        "upstream_http_status": None,
        "credits_charged": int(credits_charged),
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if isinstance(rpm_limit, int) and rpm_limit > 0 and int(key.get("requests_this_minute", 0) or 0) >= rpm_limit:
        log_row["error_code"] = "rate_limited"; log_row["error_message"] = "Per-minute request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute)")
    if isinstance(day_limit, int) and day_limit > 0 and int(key.get("requests_today", 0) or 0) >= day_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Daily request limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    if isinstance(credit_limit, int) and credit_limit > 0 and (int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)) > credit_limit:
        log_row["error_code"] = "quota_exceeded"; log_row["error_message"] = "Monthly credit limit exceeded"
        log_row["duration_ms"] = int((time.time() - _t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded")

    key["requests_this_minute"] = int(key.get("requests_this_minute", 0) or 0) + 1
    key["requests_today"] = int(key.get("requests_today", 0) or 0) + 1
    key["credits_month_to_date"] = int(key.get("credits_month_to_date", 0) or 0) + int(credits_charged)
    key["last_request_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    series = []
    for row in mkt:
        if not isinstance(row, dict):
            continue
        if row.get("record_type") != "cmc100_index_value":
            continue
        if row.get("status") not in ("fresh", "stale", "superseded"):
            continue
        asof_s = row.get("as_of")
        if not isinstance(asof_s, str):
            continue
        asof = None
        try:
            asof = datetime.datetime.fromisoformat(asof_s.replace("Z", "+00:00"))
            if asof.tzinfo is None:
                asof = asof.replace(tzinfo=datetime.timezone.utc)
            asof = asof.astimezone(datetime.timezone.utc)
        except ValueError:
            continue
        if ts and asof < ts:
            continue
        if te and asof > te:
            continue
        if interval is not None and row.get("interval") not in (None, interval):
            continue
        series.append((asof, row))

    series.sort(key=lambda t: t[0])
    if cnt is not None:
        series = series[-cnt:]

    out = []
    for asof, row in series:
        out.append({"as_of": row.get("as_of"), "numeric": row.get("numeric_fields"), "aux": row.get("aux_fields")})

    resp = {"data": out, "status": {"timestamp": _iso(now), "error_code": None, "error_message": None}}
    log_row["duration_ms"] = int((time.time() - _t0) * 1000)
    logs.append(log_row); _save("request_logs.json", logs)
    return {"data": resp}

def cmc100IndexLatest(convert=None, convert_id=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "cmc100IndexLatest"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(v)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _normalize_convert_symbol(v):
        if v is None:
            return None, None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", "convert must be a string")
        s = v.strip()
        if s == "":
            return None, None
        return s.upper(), None

    def _normalize_convert_id(v):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", "convert_id must be a string")
        if isinstance(v, (int, float)):
            if isinstance(v, float) and v != int(v):
                return None, _err("VALIDATION_ERROR", "convert_id must be an integer-like value")
            return str(int(v)), None
        if not isinstance(v, str):
            return None, _err("VALIDATION_ERROR", "convert_id must be a string")
        s = v.strip()
        if s == "":
            return None, None
        return s, None

    def _resolve_ambient_key(api_keys_rows):
        active = [r for r in api_keys_rows if isinstance(r, dict) and r.get("status") == "active" and r.get("id")]
        if not active:
            return None
        def _k(r):
            return (r.get("last_request_at") or "", r.get("updated_at") or "", r.get("created_at") or "")
        return sorted(active, key=_k, reverse=True)[0]

    def _reset_windows_if_needed(key_row):
        last = _parse_iso(key_row.get("last_request_at"))
        if last is None:
            return
        if last.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0) != now.replace(second=0, microsecond=0):
            key_row["requests_this_minute"] = 0
        if last.astimezone(datetime.timezone.utc).date() != now.date():
            key_row["requests_today"] = 0
        if (last.year, last.month) != (now.year, now.month):
            key_row["credits_month_to_date"] = 0

    def _check_and_consume(api_keys_rows, key_row, credits):
        _reset_windows_if_needed(key_row)
        rpm = int(key_row.get("requests_per_minute_limit", 0) or 0)
        rpd = int(key_row.get("requests_per_day_limit", 0) or 0)
        mcl = int(key_row.get("monthly_credit_limit", 0) or 0)
        rtmin = int(key_row.get("requests_this_minute", 0) or 0)
        rtday = int(key_row.get("requests_today", 0) or 0)
        cmt = int(key_row.get("credits_month_to_date", 0) or 0)
        if rpm > 0 and rtmin >= rpm:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded")
        if rpd > 0 and rtday >= rpd:
            return _err("QUOTA_EXCEEDED", "Per-day request limit exceeded")
        if mcl > 0 and (cmt + int(credits)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit limit exceeded")
        key_row["requests_this_minute"] = rtmin + 1
        key_row["requests_today"] = rtday + 1
        key_row["credits_month_to_date"] = cmt + int(credits)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        return None

    def _append_log(logs_rows, api_key_id, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs_rows.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged),
            "duration_ms": int(duration_ms),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })

    conv, e = _normalize_convert_symbol(convert)
    if e:
        return e
    conv_id, e = _normalize_convert_id(convert_id)
    if e:
        return e

    request_params = {}
    if conv is not None:
        request_params["convert"] = conv
    if conv_id is not None:
        request_params["convert_id"] = conv_id

    api_keys = _load("api_keys.json")
    key_row = _resolve_ambient_key(api_keys)
    cache_key = f"{tool_name}:{_stable_fingerprint(tool_name, request_params)}"
    credits = 1

    if not key_row:
        logs = _load("request_logs.json")
        _append_log(logs, "(none)", request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "unauthorized", "No active API key available")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "No active API key available")
    if key_row.get("status") != "active":
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "unauthorized", "API key not active")
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "API key not active")

    limit_err = _check_and_consume(api_keys, key_row, credits)
    if limit_err:
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, None, 0, int((time.time() - t0) * 1000),
                    "rate_limited" if limit_err["error"]["code"] == "RATE_LIMIT" else "quota_exceeded",
                    limit_err["error"]["message"][:200])
        _save("request_logs.json", logs)
        _save("api_keys.json", api_keys)
        return limit_err

    mkt = _load("market_data.json")
    values = []
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "cmc100_index_value":
            continue
        if r.get("status") == "deleted":
            continue
        if conv is not None and (r.get("convert_symbol") or "").upper() != conv:
            continue
        if conv_id is not None and str(r.get("convert_upstream_id") or "") != conv_id:
            continue
        values.append(r)

    if not values and (conv is not None or conv_id is not None):
        # fallback to latest regardless of conversion rather than NOT_FOUND
        values = [r for r in mkt if isinstance(r, dict) and r.get("record_type") == "cmc100_index_value" and r.get("status") != "deleted"]

    if not values:
        logs = _load("request_logs.json")
        _append_log(logs, key_row.get("id"), request_params, cache_key, False, 404, credits, int((time.time() - t0) * 1000),
                    "not_found", "No CMC100 index value cached"[:200])
        _save("request_logs.json", logs)
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", "No CMC100 index value cached")

    values.sort(key=lambda r: (_parse_iso(r.get("as_of")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
    latest = values[0]
    as_of = _parse_iso(latest.get("as_of"))
    as_of_s = latest.get("as_of")

    constituents = []
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "cmc100_index_constituent":
            continue
        if r.get("status") == "deleted":
            continue
        if r.get("as_of") != as_of_s and (_parse_iso(r.get("as_of")) != as_of):
            continue
        constituents.append(r)

    constituents.sort(key=lambda r: str((r.get("primary_asset_id") or "")))

    response = {
        "data": {
            "as_of": latest.get("as_of"),
            "convert": latest.get("convert_symbol"),
            "convert_id": latest.get("convert_upstream_id"),
            "index": {
                "numeric_fields": latest.get("numeric_fields") if isinstance(latest.get("numeric_fields"), dict) else {},
                "aux_fields": latest.get("aux_fields") if isinstance(latest.get("aux_fields"), dict) else {},
            },
            "constituents": [
                {
                    "primary_asset_id": r.get("primary_asset_id"),
                    "secondary_asset_id": r.get("secondary_asset_id"),
                    "numeric_fields": r.get("numeric_fields") if isinstance(r.get("numeric_fields"), dict) else {},
                    "aux_fields": r.get("aux_fields") if isinstance(r.get("aux_fields"), dict) else {},
                }
                for r in constituents
            ],
        }
    }

    logs = _load("request_logs.json")
    _append_log(logs, key_row.get("id"), request_params, cache_key, False, 200, credits, int((time.time() - t0) * 1000))
    _save("request_logs.json", logs)
    _save("api_keys.json", api_keys)
    return response

def fearAndGreedLatest(time_period=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _minute_bucket(dt):
        return dt.strftime("%Y-%m-%dT%H:%M")

    def _day_bucket(dt):
        return dt.strftime("%Y-%m-%d")

    def _month_bucket(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _stable_fingerprint(obj):
        normalized = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(normalized.encode("utf-8")).hexdigest()

    def _is_metal(asset_row):
        md = asset_row.get("metadata") if isinstance(asset_row, dict) else None
        tags = asset_row.get("tags") if isinstance(asset_row, dict) else None
        if isinstance(md, dict):
            t = md.get("type")
            if isinstance(t, str) and t.lower() in ("metal", "precious_metal", "precious-metal", "commodity_metal"):
                return True
            cat = md.get("category")
            if isinstance(cat, str) and "metal" in cat.lower():
                return True
        if isinstance(tags, list):
            for tg in tags:
                if isinstance(tg, str) and tg.lower() in ("metal", "metals", "precious-metal", "precious_metals", "precious metals"):
                    return True
        return False

    t0 = time.time()
    now = _now_utc()

    # Validate inputs (additionalProperties=false is handled by signature; validate enum)
    allowed_time_periods = {"daily", "hourly", "1m", "5m", "15m", "30m", "1h", "4h", "8h", "12h", "weekly", "monthly"}
    if time_period is not None:
        if not isinstance(time_period, str):
            return _err("VALIDATION_ERROR", "time_period must be a string.")
        if time_period not in allowed_time_periods:
            return _err("VALIDATION_ERROR", "time_period is not one of the supported values.", allowed=sorted(allowed_time_periods))

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    market_data = _load("market_data.json")
    cached_responses = _load("cached_responses.json")

    # Resolve an active API key that can serve the call (ambient auth)
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        # No key available: UNAUTHORIZED
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # Pick a key that is not rate/quota limited right now; try all to satisfy prerequisites.
    chosen = None
    for k in active_keys:
        if not isinstance(k.get("id"), str):
            continue
        rpm = k.get("requests_per_minute_limit")
        rpd = k.get("requests_per_day_limit")
        mcl = k.get("monthly_credit_limit")
        if not (isinstance(rpm, int) and isinstance(rpd, int) and isinstance(mcl, int)):
            continue

        # Reset rolling windows if boundaries passed
        last = _parse_dt(k.get("last_request_at"))
        requests_this_minute = k.get("requests_this_minute")
        requests_today = k.get("requests_today")
        credits_mtd = k.get("credits_month_to_date")
        if not (isinstance(requests_this_minute, int) and isinstance(requests_today, int) and isinstance(credits_mtd, int)):
            continue

        if last is None:
            last_min_bucket = None
            last_day_bucket = None
            last_month_bucket = None
        else:
            last_min_bucket = _minute_bucket(last.astimezone(datetime.timezone.utc))
            last_day_bucket = _day_bucket(last.astimezone(datetime.timezone.utc))
            last_month_bucket = _month_bucket(last.astimezone(datetime.timezone.utc))

        now_min_bucket = _minute_bucket(now)
        now_day_bucket = _day_bucket(now)
        now_month_bucket = _month_bucket(now)

        # simulate reset (without persisting yet) for selection logic
        sim_rtm = requests_this_minute if last_min_bucket == now_min_bucket else 0
        sim_rtd = requests_today if last_day_bucket == now_day_bucket else 0
        sim_cmt = credits_mtd if last_month_bucket == now_month_bucket else 0

        # This request's credit charge (Fear & Greed: assume 1)
        credits_charged = 1

        if rpm > 0 and sim_rtm >= rpm:
            continue
        if rpd > 0 and sim_rtd >= rpd:
            continue
        if mcl > 0 and sim_cmt + credits_charged > mcl:
            continue

        chosen = k
        break

    if chosen is None:
        # Determine which error applies by checking if any active key would pass each constraint
        # Prefer RATE_LIMIT if minute/day blocks all, else QUOTA_EXCEEDED.
        def _can_pass_rate():
            for k in active_keys:
                last = _parse_dt(k.get("last_request_at"))
                if not (isinstance(k.get("requests_per_minute_limit"), int) and isinstance(k.get("requests_per_day_limit"), int)):
                    continue
                rpm = k["requests_per_minute_limit"]
                rpd = k["requests_per_day_limit"]
                rtm = k.get("requests_this_minute")
                rtd = k.get("requests_today")
                if not (isinstance(rtm, int) and isinstance(rtd, int)):
                    continue
                last_min_bucket = _minute_bucket(last) if last else None
                last_day_bucket = _day_bucket(last) if last else None
                sim_rtm = rtm if last_min_bucket == _minute_bucket(now) else 0
                sim_rtd = rtd if last_day_bucket == _day_bucket(now) else 0
                if (rpm == 0 or sim_rtm < rpm) and (rpd == 0 or sim_rtd < rpd):
                    return True
            return False

        if not _can_pass_rate():
            return _err("RATE_LIMIT", "Rate limit exceeded for all available API keys.")
        return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded for all available API keys.")

    # Enforce windows + increment counters for chosen key (this call counts even if cache miss or empty data)
    last = _parse_dt(chosen.get("last_request_at"))
    if last is None or _minute_bucket(last) != _minute_bucket(now):
        chosen["requests_this_minute"] = 0
    if last is None or _day_bucket(last) != _day_bucket(now):
        chosen["requests_today"] = 0
    if last is None or _month_bucket(last) != _month_bucket(now):
        chosen["credits_month_to_date"] = 0

    # Re-check after reset for strict enforcement
    rpm = chosen["requests_per_minute_limit"]
    rpd = chosen["requests_per_day_limit"]
    mcl = chosen["monthly_credit_limit"]
    if rpm > 0 and chosen["requests_this_minute"] >= rpm:
        # log and return
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "fearAndGreedLatest",
            "request_params": {} if time_period is None else {"time_period": time_period},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limited",
            "error_message": "requests_per_minute_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Requests per minute limit exceeded.")
    if rpd > 0 and chosen["requests_today"] >= rpd:
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "fearAndGreedLatest",
            "request_params": {} if time_period is None else {"time_period": time_period},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limited",
            "error_message": "requests_per_day_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Requests per day limit exceeded.")
    credits_charged = 1
    if mcl > 0 and chosen["credits_month_to_date"] + credits_charged > mcl:
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "fearAndGreedLatest",
            "request_params": {} if time_period is None else {"time_period": time_period},
            "cache_key": None,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
