            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly credit limit exceeded.")

    chosen["requests_this_minute"] += 1
    chosen["requests_today"] += 1
    chosen["credits_month_to_date"] += credits_charged
    chosen["last_request_at"] = _iso(now)
    chosen["updated_at"] = _iso(now)

    # Optional caching for map results (short TTL)
    normalized_params = {"start": start, "limit": limit, "sort": sort, "include_metals": include_metals}
    params_fingerprint = _stable_fingerprint(normalized_params)
    cache_key = f"fiatMap:{params_fingerprint}"

    cache_row = None
    for r in cached_responses:
        if isinstance(r, dict) and r.get("tool_name") == "fiatMap" and r.get("params_fingerprint") == params_fingerprint:
            cache_row = r
            break

    cache_hit = False
    response_body = None

    def _project(row):
        return {
            "id": row.get("upstream_id"),
            "name": row.get("name"),
            "sign": (row.get("metadata") or {}).get("sign"),
            "symbol": row.get("symbol"),
        }

    if cache_row and cache_row.get("status") == "valid":
        exp = _parse_dt(cache_row.get("expires_at"))
        if exp and exp > now:
            cache_hit = True
            response_body = cache_row.get("response_body")

    if not cache_hit:
        fiats = []
        for row in asset_directory:
            if not isinstance(row, dict):
                continue
            if row.get("entity_type") != "fiat":
                continue
            if row.get("status") == "deleted":
                continue
            if not include_metals and _is_metal(row):
                continue
            fiats.append(row)

        # deterministic sort
        def _sort_key(r):
            v = r.get(sort)
            if v is None:
                return (1, "")
            if isinstance(v, (int, float)):
                return (0, v)
            return (0, str(v).lower())

        fiats.sort(key=_sort_key)
        total = len(fiats)

        offset = start - 1
        page = fiats[offset:offset + limit] if offset < total else []
        data = [_project(r) for r in page]

        response_body = {
            "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None},
            "data": data,
            "meta": {
                "total": total,
                "start": start,
                "limit": limit,
                "has_more": (offset + limit) < total,
                "next_start": (start + limit) if (offset + limit) < total else None,
            }
        }

        # cache for 5 minutes
        expires_at = now + datetime.timedelta(minutes=5)
        if cache_row is None:
            cached_responses.append({
                "id": _gen_id("cache"),
                "tool_name": "fiatMap",
                "params_fingerprint": params_fingerprint,
                "request_params": normalized_params,
                "response_body": response_body,
                "http_status": 200,
                "etag": None,
                "expires_at": _iso(expires_at),
                "status": "valid",
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
        else:
            cache_row["request_params"] = normalized_params
            cache_row["response_body"] = response_body
            cache_row["http_status"] = 200
            cache_row["expires_at"] = _iso(expires_at)
            cache_row["status"] = "valid"
            cache_row["updated_at"] = _iso(now)
        _save("cached_responses.json", cached_responses)

    duration_ms = max(0, int((time.time() - t0) * 1000))
    log_id = _gen_id("rql")
    request_logs.append({
        "id": log_id,
        "api_key_id": chosen["id"],
        "tool_name": "fiatMap",
        "request_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": bool(cache_hit),
        "upstream_http_status": 200,
        "credits_charged": int(credits_charged),
        "duration_ms": int(duration_ms),
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)
    _save("api_keys.json", api_keys)

    # Return in same envelope as response_body
    return response_body

def getPostmanCollection(version=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _minute_bucket(dt):
        return dt.strftime("%Y-%m-%dT%H:%M")

    def _day_bucket(dt):
        return dt.strftime("%Y-%m-%d")

    def _month_bucket(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _stable_fingerprint(obj):
        normalized = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(normalized.encode("utf-8")).hexdigest()

    t0 = time.time()
    now = _now_utc()

    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string when provided.")

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    cached_responses = _load("cached_responses.json")

    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # choose key with capacity; Postman doc still counts (credits=1)
    chosen = None
    credits_charged = 1
    for k in active_keys:
        if not isinstance(k.get("id"), str):
            continue
        if not (isinstance(k.get("requests_per_minute_limit"), int) and isinstance(k.get("requests_per_day_limit"), int) and isinstance(k.get("monthly_credit_limit"), int)):
            continue
        if not (isinstance(k.get("requests_this_minute"), int) and isinstance(k.get("requests_today"), int) and isinstance(k.get("credits_month_to_date"), int)):
            continue
        last = _parse_dt(k.get("last_request_at"))
        sim_rtm = k["requests_this_minute"] if last and _minute_bucket(last) == _minute_bucket(now) else 0
        sim_rtd = k["requests_today"] if last and _day_bucket(last) == _day_bucket(now) else 0
        sim_cmt = k["credits_month_to_date"] if last and _month_bucket(last) == _month_bucket(now) else 0
        rpm = k["requests_per_minute_limit"]
        rpd = k["requests_per_day_limit"]
        mcl = k["monthly_credit_limit"]
        if rpm > 0 and sim_rtm >= rpm:
            continue
        if rpd > 0 and sim_rtd >= rpd:
            continue
        if mcl > 0 and sim_cmt + credits_charged > mcl:
            continue
        chosen = k
        break

    if chosen is None:
        return _err("RATE_LIMIT", "Rate limit or quota exceeded for all available API keys.")

    # reset + enforce chosen
    last = _parse_dt(chosen.get("last_request_at"))
    if last is None or _minute_bucket(last) != _minute_bucket(now):
        chosen["requests_this_minute"] = 0
    if last is None or _day_bucket(last) != _day_bucket(now):
        chosen["requests_today"] = 0
    if last is None or _month_bucket(last) != _month_bucket(now):
        chosen["credits_month_to_date"] = 0

    rpm = chosen["requests_per_minute_limit"]
    rpd = chosen["requests_per_day_limit"]
    mcl = chosen["monthly_credit_limit"]
    normalized_params = {} if version is None else {"version": version}
    params_fingerprint = _stable_fingerprint(normalized_params)
    cache_key = f"getPostmanCollection:{params_fingerprint}"

    if rpm > 0 and chosen["requests_this_minute"] >= rpm:
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "getPostmanCollection",
            "request_params": normalized_params,
            "cache_key": cache_key,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limited",
            "error_message": "requests_per_minute_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Requests per minute limit exceeded.")
    if rpd > 0 and chosen["requests_today"] >= rpd:
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "getPostmanCollection",
            "request_params": normalized_params,
            "cache_key": cache_key,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "rate_limited",
            "error_message": "requests_per_day_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("RATE_LIMIT", "Requests per day limit exceeded.")
    if mcl > 0 and chosen["credits_month_to_date"] + credits_charged > mcl:
        log_id = _gen_id("rql")
        duration_ms = max(0, int((time.time() - t0) * 1000))
        request_logs.append({
            "id": log_id,
            "api_key_id": chosen["id"],
            "tool_name": "getPostmanCollection",
            "request_params": normalized_params,
            "cache_key": cache_key,
            "cache_hit": False,
            "upstream_http_status": None,
            "credits_charged": 0,
            "duration_ms": duration_ms,
            "error_code": "quota_exceeded",
            "error_message": "monthly_credit_limit exceeded",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", request_logs)
        _save("api_keys.json", api_keys)
        return _err("QUOTA_EXCEEDED", "Monthly credit limit exceeded.")

    chosen["requests_this_minute"] += 1
    chosen["requests_today"] += 1
    chosen["credits_month_to_date"] += credits_charged
    chosen["last_request_at"] = _iso(now)
    chosen["updated_at"] = _iso(now)

    # Cache lookup (long TTL; cache is authoritative for versions)
    cache_hit = False
    cache_row = None
    for r in cached_responses:
        if isinstance(r, dict) and r.get("tool_name") == "getPostmanCollection" and r.get("params_fingerprint") == params_fingerprint:
            cache_row = r
            break

    def _cache_is_valid(r):
        if not r or r.get("status") != "valid":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return bool(exp and exp > now)

    # If version specified, require it to exist; we treat cached entries as the version store.
    # If version omitted: use latest available among valid OR expired (but not purged) entries.
    selected = None
    if version is not None:
        # find any matching version entry (valid/expired) then decide if usable
        if cache_row is None:
            # maybe exists under different fingerprint if version normalization differs; do direct scan
            for r in cached_responses:
                if not isinstance(r, dict):
                    continue
                if r.get("tool_name") != "getPostmanCollection":
                    continue
                rp = r.get("request_params")
                if isinstance(rp, dict) and rp.get("version") == version:
                    cache_row = r
                    break
        if cache_row is None or cache_row.get("status") == "purged":
            # log + not found
            duration_ms = max(0, int((time.time() - t0) * 1000))
            log_id = _gen_id("rql")
            request_logs.append({
                "id": log_id,
                "api_key_id": chosen["id"],
                "tool_name": "getPostmanCollection",
                "request_params": normalized_params,
                "cache_key": cache_key,
                "cache_hit": False,
                "upstream_http_status": 404,
                "credits_charged": int(credits_charged),
                "duration_ms": int(duration_ms),
                "error_code": "not_found",
                "error_message": "requested Postman collection version not found",
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("request_logs.json", request_logs)
            _save("api_keys.json", api_keys)
            return _err("NOT_FOUND", "Requested Postman collection version does not exist.", version=version)

        # If expired, revive by extending TTL (allowed expired->valid)
        if _cache_is_valid(cache_row):
            cache_hit = True
            selected = cache_row
        else:
            # revive and return (still not a cache hit since it required refresh)
            ttl_days = 90
            cache_row["expires_at"] = _iso(now + datetime.timedelta(days=ttl_days))
            cache_row["status"] = "valid"
            cache_row["updated_at"] = _iso(now)
            _save("cached_responses.json", cached_responses)
            selected = cache_row
    else:
        # Choose latest version among existing cached_responses tool entries not purged.
        # Prefer valid; if none valid, allow expired entries.
        candidates = []
        for r in cached_responses:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != "getPostmanCollection":
                continue
            if r.get("status") == "purged":
                continue
            rp = r.get("request_params") if isinstance(r.get("request_params"), dict) else {}
            ver = rp.get("version")
            if ver is None:
                continue
            # sort by updated_at then created_at
            ud = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or now
            candidates.append((ud, ver, r))

        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            # prefer first valid in that ordering
            valid_first = None
            for ud, ver, r in candidates:
                if _cache_is_valid(r):
                    valid_first = r
                    break
            if valid_first is not None:
                cache_hit = True
                selected = valid_first
            else:
                # revive the most recently updated expired
                selected = candidates[0][2]
                ttl_days = 90
                selected["expires_at"] = _iso(now + datetime.timedelta(days=ttl_days))
                selected["status"] = "valid"
                selected["updated_at"] = _iso(now)
                _save("cached_responses.json", cached_responses)
        else:
            # No stored versions: synthesize a static document and store as "latest"
            latest_version = "latest"
            doc = {
                "info": {
                    "name": "CoinMarketCap API (Offline Cache)",
                    "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json",
                    "version": latest_version,
                    "description": "Static Postman collection document served by MCP cache (offline)."
                },
                "item": []
            }
            ttl_days = 365
            selected = {
                "id": _gen_id("cache"),
                "tool_name": "getPostmanCollection",
                "params_fingerprint": _stable_fingerprint({"version": latest_version}),
                "request_params": {"version": latest_version},
                "response_body": doc,
                "http_status": 200,
                "etag": None,
                "expires_at": _iso(now + datetime.timedelta(days=ttl_days)),
                "status": "valid",
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            cached_responses.append(selected)
            _save("cached_responses.json", cached_responses)
            cache_hit = False

    response_body = selected.get("response_body") if isinstance(selected, dict) else None
    http_status = selected.get("http_status") if isinstance(selected, dict) else 200
    if response_body is None:
        response_body = {}

    duration_ms = max(0, int((time.time() - t0) * 1000))
    log_id = _gen_id("rql")
    request_logs.append({
        "id": log_id,
        "api_key_id": chosen["id"],
        "tool_name": "getPostmanCollection",
        "request_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": bool(cache_hit),
        "upstream_http_status": int(http_status) if isinstance(http_status, int) else 200,
        "credits_charged": int(credits_charged),
        "duration_ms": int(duration_ms),
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("request_logs.json", request_logs)
    _save("api_keys.json", api_keys)

    return {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None},
        "data": response_body,
        "meta": {
            "cache": {"hit": bool(cache_hit), "key": cache_key},
            "version": (normalized_params.get("version") if version is not None else ((selected.get("request_params") or {}).get("version") if isinstance(selected, dict) else None))
        }
    }

def priceConversion(amount, id=None, symbol=None, time=None, convert=None, convert_id=None, **_extra):
    import json, os, datetime, time as _time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = _time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "priceConversion"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _stable_fingerprint(tool, params_obj):
        payload = json.dumps(params_obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256((tool + "|" + payload).encode("utf-8")).hexdigest()

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _resolve_active_api_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "No active API key context available")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    # validate
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount != amount:
        return _err("VALIDATION_ERROR", "amount is required and must be a number")
    request_params = {"amount": float(amount)}

    if id is not None:
        if not isinstance(id, str) or not id.strip():
            return _err("VALIDATION_ERROR", "id must be a non-empty string when provided")
        request_params["id"] = id.strip()
    if symbol is not None:
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided")
        request_params["symbol"] = symbol.strip().upper()
    if id is None and symbol is None:
        return _err("VALIDATION_ERROR", "Either id or symbol must be provided as the source currency")
    if time is not None:
        if not isinstance(time, str) or not time.strip():
            return _err("VALIDATION_ERROR", "time must be an ISO datetime string when provided")
        # accept but do not require parseable; if parseable, use as target time (<= now)
        request_params["time"] = time.strip()

    if convert is not None:
        if not isinstance(convert, str) or not convert.strip():
            return _err("VALIDATION_ERROR", "convert must be a non-empty string when provided")
        request_params["convert"] = convert.strip().upper()
    if convert_id is not None:
        if isinstance(convert_id, (int, float)) and not isinstance(convert_id, bool):
            convert_id = str(int(convert_id))
        if not isinstance(convert_id, str) or not convert_id.strip():
            return _err("VALIDATION_ERROR", "convert_id must be a non-empty string when provided")
        request_params["convert_id"] = convert_id.strip()

    if convert is None and convert_id is None:
        # align with common CMC behavior: default to USD if nothing supplied
        request_params["convert"] = "USD"

    api_key_row = _resolve_active_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to serve request")

    credits = 1
    fp = _stable_fingerprint(tool_name, request_params)
    cache_key = f"{tool_name}:{fp}"

    cached_rows = _load("cached_responses.json")
    if isinstance(cached_rows, list):
        for c in cached_rows:
            if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
                if c.get("status") == "valid":
                    exp = _parse_iso(c.get("expires_at"))
                    if exp and exp > now and isinstance(c.get("response_body"), dict):
                        qerr = _enforce_and_increment(api_key_row, credits)
                        if qerr:
                            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((_time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
                            return qerr
                        _append_log(api_key_row.get("id"), request_params, cache_key, True, c.get("http_status"), credits, int((_time.time() - t0) * 1000))
                        return c["response_body"]
                break

    # Resolve source asset by upstream_id (id) or symbol within asset_directory
    assets = _load("asset_directory.json")
    if not isinstance(assets, list):
        assets = []
    cryptos = [a for a in assets if isinstance(a, dict) and a.get("entity_type") in ("cryptocurrency", "fiat") and a.get("status") != "deleted"]

    source_asset = None
    if id is not None:
        for a in cryptos:
            if str(a.get("upstream_id")) == id.strip():
                source_asset = a
                break
    if source_asset is None and symbol is not None:
        sym = symbol.strip().upper()
        for a in cryptos:
            if str(a.get("symbol") or "").upper() == sym:
                source_asset = a
                break
    if source_asset is None:
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((_time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((_time.time() - t0) * 1000), error_code="not_found", error_message="Source currency not found")
        return _err("NOT_FOUND", "Source currency not found")

    conv_sym = request_params.get("convert")
    conv_id = request_params.get("convert_id")

    mkt = _load("market_data.json")
    if not isinstance(mkt, list):
        mkt = []

    target_time = _parse_iso(request_params.get("time")) if request_params.get("time") is not None else None
    if target_time and target_time > now:
        target_time = now

    def _match_convert(r):
        if conv_sym is None and conv_id is None:
            return (r.get("convert_symbol") in (None, "",)) and (r.get("convert_upstream_id") in (None, "",))
        ok = True
        if conv_sym is not None:
            ok = ok and (str(r.get("convert_symbol") or "").upper() == str(conv_sym).upper())
        if conv_id is not None:
            ok = ok and (str(r.get("convert_upstream_id") or "") == str(conv_id))
        return ok

    # Find best quote at or before target_time (or latest if no time)
    best = None
    best_dt = None
    for r in mkt:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "crypto_quote_latest":
            continue
        if r.get("status") in ("deleted",):
            continue
        if r.get("primary_asset_id") != source_asset.get("id"):
            continue
        if not _match_convert(r):
            continue
        as_of = _parse_iso(r.get("as_of"))
        if as_of is None:
            continue
        if target_time and as_of > target_time:
            continue
        if best is None or (best_dt is not None and as_of > best_dt) or best_dt is None:
            best = r
            best_dt = as_of

    if best is None:
        # If no converted quote exists, attempt to compute via USD pivot if possible:
        # - get source quote in USD
        # - get target fiat/crypto rate vs USD? not available; so fail with NOT_FOUND.
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((_time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 404, 0, int((_time.time() - t0) * 1000), error_code="not_found", error_message="No suitable quote found for conversion request")
        return _err("NOT_FOUND", "No suitable quote found for conversion request")

    numeric = best.get("numeric_fields", {}) if isinstance(best.get("numeric_fields"), dict) else {}
    price = numeric.get("price")
    if not isinstance(price, (int, float)):
        qerr = _enforce_and_increment(api_key_row, 0)
        if qerr:
            _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((_time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
            return qerr
        _append_log(api_key_row.get("id"), request_params, cache_key, False, 502, 0, int((_time.time() - t0) * 1000), error_code="upstream_error", error_message="Cached quote missing numeric_fields.price")
        return _err("NOT_FOUND", "Cached quote missing price for conversion")

    converted = float(amount) * float(price)

    response = {
        "status": {"timestamp": _iso(now), "error_code": 0, "error_message": None},
        "data": {
            "amount": float(amount),
            "source": {
                "id": source_asset.get("id"),
                "upstream_id": source_asset.get("upstream_id"),
                "symbol": source_asset.get("symbol"),
                "name": source_asset.get("name"),
            },
            "quote": {
                "price": float(price),
                "as_of": best.get("as_of"),
                "convert": conv_sym,
                "convert_id": conv_id,
                "converted_amount": float(converted),
            }
        }
    }

    qerr = _enforce_and_increment(api_key_row, credits)
    if qerr:
        _append_log(api_key_row.get("id"), request_params, cache_key, False, None, 0, int((_time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr
    _append_log(api_key_row.get("id"), request_params, cache_key, False, 200, credits, int((_time.time() - t0) * 1000))

    # cache write-through very short TTL
    cached_rows = _load("cached_responses.json")
    if not isinstance(cached_rows, list):
        cached_rows = []
    expires = now + datetime.timedelta(seconds=30)
    existing_idx = None
    for i, c in enumerate(cached_rows):
        if isinstance(c, dict) and c.get("tool_name") == tool_name and c.get("params_fingerprint") == fp:
            existing_idx = i
            break
    row = {
        "id": _new_id("cmc_cache"),
        "tool_name": tool_name,
        "params_fingerprint": fp,
        "request_params": request_params,
        "response_body": response,
        "http_status": 200,
        "etag": None,
        "expires_at": _iso(expires),
        "status": "valid",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    if existing_idx is None:
        cached_rows.append(row)
    else:
        row["id"] = cached_rows[existing_idx].get("id") or row["id"]
        row["created_at"] = cached_rows[existing_idx].get("created_at") or row["created_at"]
        cached_rows[existing_idx] = row
    _save("cached_responses.json", cached_rows)

    return response

def keyInfo(api_key_id=None, key_prefix=None, **_extra):
    import json, os, datetime, time as _time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = _time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        import secrets
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _log(api_key_id_used, tool_name, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        ts = _iso(now)
        row = {
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged),
            "duration_ms": int(duration_ms),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _reset_windows_if_needed(krow):
        last = _parse_dt(krow.get("last_request_at"))
        if last is None:
            return
        if (last.year, last.month, last.day, last.hour, last.minute) != (now.year, now.month, now.day, now.hour, now.minute):
            krow["requests_this_minute"] = 0
        if (last.year, last.month, last.day) != (now.year, now.month, now.day):
            krow["requests_today"] = 0
        if (last.year, last.month) != (now.year, now.month):
            krow["credits_month_to_date"] = 0

    def _enforce_and_consume(keys_all, krow, credits_needed):
        _reset_windows_if_needed(krow)
        rpm_lim = krow.get("requests_per_minute_limit")
        rpd_lim = krow.get("requests_per_day_limit")
        mcred_lim = krow.get("monthly_credit_limit")
        if not isinstance(rpm_lim, int) or rpm_lim < 0:
            return _err("VALIDATION_ERROR", "Stored requests_per_minute_limit invalid.")
        if not isinstance(rpd_lim, int) or rpd_lim < 0:
            return _err("VALIDATION_ERROR", "Stored requests_per_day_limit invalid.")
        if not isinstance(mcred_lim, int) or mcred_lim < 0:
            return _err("VALIDATION_ERROR", "Stored monthly_credit_limit invalid.")
        if rpm_lim > 0 and int(krow.get("requests_this_minute", 0)) >= rpm_lim:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if rpd_lim > 0 and int(krow.get("requests_today", 0)) >= rpd_lim:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if mcred_lim > 0 and (int(krow.get("credits_month_to_date", 0)) + int(credits_needed)) > mcred_lim:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded.")
        krow["requests_this_minute"] = int(krow.get("requests_this_minute", 0)) + 1
        krow["requests_today"] = int(krow.get("requests_today", 0)) + 1
        krow["credits_month_to_date"] = int(krow.get("credits_month_to_date", 0)) + int(credits_needed)
        krow["last_request_at"] = _iso(now)
        krow["updated_at"] = _iso(now)
        _save("api_keys.json", keys_all)
        return None

    # Validation
    req_params = {}
    if api_key_id is not None:
        req_params["api_key_id"] = api_key_id
    if key_prefix is not None:
        req_params["key_prefix"] = key_prefix

    if api_key_id is None and key_prefix is None:
        # still must log; choose any active key for the call
        keys_all = _load("api_keys.json")
        active = [k for k in keys_all if k.get("status") == "active"]
        if not active:
            return _err("UNAUTHORIZED", "No active API key available to serve this request.")
        used = active[0]
        err = _err("VALIDATION_ERROR", "Either api_key_id or key_prefix must be provided.")
        duration_ms = int((_time.time() - t0) * 1000)
        _log(used["id"], "keyInfo", req_params, None, False, None, 0, duration_ms, "validation_error", err["error"]["message"][:240])
        return err

    if api_key_id is not None:
        if not isinstance(api_key_id, str):
            keys_all = _load("api_keys.json")
            active = [k for k in keys_all if k.get("status") == "active"]
            if not active:
                return _err("UNAUTHORIZED", "No active API key available to serve this request.")
            used = active[0]
            err = _err("VALIDATION_ERROR", "api_key_id must be a string.")
            duration_ms = int((_time.time() - t0) * 1000)
            _log(used["id"], "keyInfo", req_params, None, False, None, 0, duration_ms, "validation_error", err["error"]["message"][:240])
            return err
        pat = re.compile(r"^cmc_key_[0-9A-HJKMNP-TV-Z]{26}$")
        if not pat.match(api_key_id):
            keys_all = _load("api_keys.json")
            active = [k for k in keys_all if k.get("status") == "active"]
            if not active:
                return _err("UNAUTHORIZED", "No active API key available to serve this request.")
            used = active[0]
            err = _err("VALIDATION_ERROR", "api_key_id is malformed.")
            duration_ms = int((_time.time() - t0) * 1000)
            _log(used["id"], "keyInfo", req_params, None, False, None, 0, duration_ms, "validation_error", err["error"]["message"][:240])
            return err

    if key_prefix is not None and not isinstance(key_prefix, str):
        keys_all = _load("api_keys.json")
        active = [k for k in keys_all if k.get("status") == "active"]
        if not active:
            return _err("UNAUTHORIZED", "No active API key available to serve this request.")
        used = active[0]
        err = _err("VALIDATION_ERROR", "key_prefix must be a string.")
        duration_ms = int((_time.time() - t0) * 1000)
        _log(used["id"], "keyInfo", req_params, None, False, None, 0, duration_ms, "validation_error", err["error"]["message"][:240])
        return err

    # AUTH ambient: pick an active key to bill/limit this request
    keys_all = _load("api_keys.json")
    active = [k for k in keys_all if k.get("status") == "active"]
    if not active:
        return _err("UNAUTHORIZED", "No active API key available to serve this request.")
    caller_key = active[0]

    credits_needed = 1
    consume_err = _enforce_and_consume(keys_all, caller_key, credits_needed)
    if consume_err:
        duration_ms = int((_time.time() - t0) * 1000)
        _log(caller_key["id"], "keyInfo", req_params, None, False, None, 0, duration_ms, consume_err["error"]["code"].lower(), consume_err["error"]["message"][:240])
        return consume_err

    # Find requested key
    target = None
    if api_key_id is not None:
        for k in keys_all:
            if k.get("id") == api_key_id:
                target = k
                break
    if target is None and key_prefix is not None:
        kp = key_prefix.strip()
        for k in keys_all:
            if (k.get("key_prefix") or "") == kp:
                target = k
                break

    if target is None:
        duration_ms = int((_time.time() - t0) * 1000)
        _log(caller_key["id"], "keyInfo", req_params, None, False, None, credits_needed, duration_ms, "not_found", "API key not found")
        return _err("NOT_FOUND", "API key not found for the provided identifier.")

    # "UNAUTHORIZED/FORBIDDEN if caller not permitted" - no account model provided; allow within service.
    body = {
        "status": {
            "timestamp": _iso(now),
            "error_code": 0,
            "error_message": None,
            "elapsed": int((_time.time() - t0) * 1000),
            "credit_count": credits_needed
        },
        "data": {
            "id": target.get("id"),
            "key_prefix": target.get("key_prefix"),
            "label": target.get("label"),
            "status": target.get("status"),
            "plan": target.get("plan"),
            "requests_per_minute_limit": target.get("requests_per_minute_limit"),
            "requests_per_day_limit": target.get("requests_per_day_limit"),
            "monthly_credit_limit": target.get("monthly_credit_limit"),
            "requests_today": target.get("requests_today"),
            "requests_this_minute": target.get("requests_this_minute"),
            "credits_month_to_date": target.get("credits_month_to_date"),
            "last_request_at": target.get("last_request_at"),
            "created_at": target.get("created_at"),
            "updated_at": target.get("updated_at"),
        }
    }

    duration_ms = int((_time.time() - t0) * 1000)
    _log(caller_key["id"], "keyInfo", req_params, None, False, 200, credits_needed, duration_ms, None, None)
    return body

def createApiKey(api_key, label, plan, requests_per_minute_limit=None, requests_per_day_limit=None, monthly_credit_limit=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    tool_name = "createApiKey"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "Invalid api_key")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    def _coerce_limit(v, name):
        if v is None:
            return None
        if isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number")
        if isinstance(v, (int, float)):
            if v != v:
                return _err("VALIDATION_ERROR", f"{name} must be a number")
            iv = int(v)
            if abs(v - iv) > 1e-9:
                return _err("VALIDATION_ERROR", f"{name} must be an integer")
            if iv < 0:
                return _err("VALIDATION_ERROR", f"{name} must be >= 0")
            return iv
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return _err("VALIDATION_ERROR", f"{name} must be a non-empty stringified integer")
            try:
                iv = int(s)
            except ValueError:
                return _err("VALIDATION_ERROR", f"{name} must be an integer")
            if iv < 0:
                return _err("VALIDATION_ERROR", f"{name} must be >= 0")
            return iv
        return _err("VALIDATION_ERROR", f"{name} must be a number")

    # Validate required fields
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(label, str) or not label.strip():
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")
    if not isinstance(plan, str) or not plan.strip():
        return _err("VALIDATION_ERROR", "plan is required and must be a non-empty string")

    plan_norm = plan.strip().lower()
    # tool schema includes 'basic' but datastore schema doesn't; map basic->pro
    if plan_norm == "basic":
        plan_norm = "pro"
    if plan_norm not in ("free", "pro", "enterprise"):
        return _err("VALIDATION_ERROR", "plan must be one of: free, basic, pro, enterprise")

    rpm = _coerce_limit(requests_per_minute_limit, "requests_per_minute_limit")
    if isinstance(rpm, dict) and "error" in rpm:
        return rpm
    rpd = _coerce_limit(requests_per_day_limit, "requests_per_day_limit")
    if isinstance(rpd, dict) and "error" in rpd:
        return rpd
    mcl = _coerce_limit(monthly_credit_limit, "monthly_credit_limit")
    if isinstance(mcl, dict) and "error" in mcl:
        return mcl

    # Authenticate api_key parameter: match against stored key_prefix OR id (client-visible), never key_hash
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []

    presented = api_key.strip()
    presented_prefix = presented[:8]

    caller = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == presented or k.get("key_prefix") == presented or k.get("key_prefix") == presented_prefix:
            caller = k
            break

    if caller is None:
        # log as request with unknown api key not possible due to FK; return unauthorized without logging
        return _err("UNAUTHORIZED", "Invalid api_key")

    request_params = {
        "api_key": presented,  # schema-allowed; yes it is sensitive but tool schema says it's provided
        "label": label.strip(),
        "plan": plan.strip(),
    }
    if rpm is not None:
        request_params["requests_per_minute_limit"] = rpm
    if rpd is not None:
        request_params["requests_per_day_limit"] = rpd
    if mcl is not None:
        request_params["monthly_credit_limit"] = mcl

    # Enforce quota/rate for this management call too
    qerr = _enforce_and_increment(caller, 1)
    if qerr:
        _append_log(caller.get("id"), request_params, None, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr

    # Create new key record
    new_prefix = "cmc_" + secrets.token_hex(4)  # 12 chars-ish; must be unique
    existing_prefixes = {k.get("key_prefix") for k in keys if isinstance(k, dict)}
    tries = 0
    while new_prefix in existing_prefixes and tries < 50:
        new_prefix = "cmc_" + secrets.token_hex(4)
        tries += 1
    if new_prefix in existing_prefixes:
        _append_log(caller.get("id"), request_params, None, False, 409, 0, int((time.time() - t0) * 1000), error_code="conflict", error_message="Unable to generate unique key_prefix")
        return _err("CONFLICT", "Unable to generate unique key_prefix")

    # Label uniqueness is not declared in schema; enforce only key_prefix/key_hash uniqueness.
    new_id = _new_id("cmc_key")
    created = _iso(now)
    new_row = {
        "id": new_id,
        "key_hash": hashlib.sha256((new_id + "|" + new_prefix).encode("utf-8")).hexdigest(),
        "key_prefix": new_prefix,
        "label": label.strip(),
        "status": "active",
        "plan": plan_norm,
        "requests_per_minute_limit": int(rpm if rpm is not None else 0),
        "requests_per_day_limit": int(rpd if rpd is not None else 0),
        "monthly_credit_limit": int(mcl if mcl is not None else 0),
        "requests_today": 0,
        "requests_this_minute": 0,
        "credits_month_to_date": 0,
        "last_request_at": None,
        "created_at": created,
        "updated_at": created,
    }

    # ensure unique key_hash/key_prefix
    existing_hashes = {k.get("key_hash") for k in keys if isinstance(k, dict)}
    if new_row["key_hash"] in existing_hashes or new_row["key_prefix"] in existing_prefixes:
        _append_log(caller.get("id"), request_params, None, False, 409, 0, int((time.time() - t0) * 1000), error_code="conflict", error_message="Key uniqueness constraint violated (key_hash or key_prefix)")
        return _err("CONFLICT", "Key uniqueness constraint violated (key_hash or key_prefix)")

    keys.append(new_row)
    _save("api_keys.json", keys)

    _append_log(caller.get("id"), request_params, None, False, 201, 1, int((time.time() - t0) * 1000))

    return {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": new_row}

def updateApiKey(api_key, id, label=None, plan=None, requests_per_minute_limit=None, requests_per_day_limit=None, monthly_credit_limit=None, status=None, **_extra):
    import json, os, datetime, time as _time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = _time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        import secrets
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _log(api_key_id_used, tool_name, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        ts = _iso(now)
        row = {
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": tool_name,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged),
            "duration_ms": int(duration_ms),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _reset_windows_if_needed(krow):
        last = _parse_dt(krow.get("last_request_at"))
        if last is None:
            return
        if (last.year, last.month, last.day, last.hour, last.minute) != (now.year, now.month, now.day, now.hour, now.minute):
            krow["requests_this_minute"] = 0
        if (last.year, last.month, last.day) != (now.year, now.month, now.day):
            krow["requests_today"] = 0
        if (last.year, last.month) != (now.year, now.month):
            krow["credits_month_to_date"] = 0

    def _enforce_and_consume(keys_all, krow, credits_needed):
        _reset_windows_if_needed(krow)
        rpm_lim = krow.get("requests_per_minute_limit")
        rpd_lim = krow.get("requests_per_day_limit")
        mcred_lim = krow.get("monthly_credit_limit")
        if not isinstance(rpm_lim, int) or rpm_lim < 0:
            return _err("VALIDATION_ERROR", "Stored requests_per_minute_limit invalid.")
        if not isinstance(rpd_lim, int) or rpd_lim < 0:
            return _err("VALIDATION_ERROR", "Stored requests_per_day_limit invalid.")
        if not isinstance(mcred_lim, int) or mcred_lim < 0:
            return _err("VALIDATION_ERROR", "Stored monthly_credit_limit invalid.")
        if rpm_lim > 0 and int(krow.get("requests_this_minute", 0)) >= rpm_lim:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if rpd_lim > 0 and int(krow.get("requests_today", 0)) >= rpd_lim:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if mcred_lim > 0 and (int(krow.get("credits_month_to_date", 0)) + int(credits_needed)) > mcred_lim:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded.")
        krow["requests_this_minute"] = int(krow.get("requests_this_minute", 0)) + 1
        krow["requests_today"] = int(krow.get("requests_today", 0)) + 1
        krow["credits_month_to_date"] = int(krow.get("credits_month_to_date", 0)) + int(credits_needed)
        krow["last_request_at"] = _iso(now)
        krow["updated_at"] = _iso(now)
        _save("api_keys.json", keys_all)
        return None

    # Validate inputs
    req_params = {"api_key": api_key, "id": id}
    if label is not None:
        req_params["label"] = label
    if plan is not None:
        req_params["plan"] = plan
    if requests_per_minute_limit is not None:
        req_params["requests_per_minute_limit"] = requests_per_minute_limit
    if requests_per_day_limit is not None:
        req_params["requests_per_day_limit"] = requests_per_day_limit
    if monthly_credit_limit is not None:
        req_params["monthly_credit_limit"] = monthly_credit_limit
    if status is not None:
        req_params["status"] = status

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if label is not None and (not isinstance(label, str) or not label.strip()):
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided.")

    if plan is not None:
        if not isinstance(plan, str):
            return _err("VALIDATION_ERROR", "plan must be a string.")
        plan_in = plan.strip().lower()
        if plan_in not in ("free", "basic", "pro", "enterprise"):
            return _err("VALIDATION_ERROR", "plan must be one of: free, basic, pro, enterprise.")
        plan_store = "pro" if plan_in == "basic" else plan_in
    else:
        plan_store = None

    def _to_nonneg_int(v, field):
        if v is None:
            return None
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return _err("VALIDATION_ERROR", f"{field} must be a number.")
        if int(v) != v:
            if abs(v - int(v)) > 1e-9:
                return _err("VALIDATION_ERROR", f"{field} must be an integer.")
        iv = int(v)
        if iv < 0:
            return _err("VALIDATION_ERROR", f"{field} must be >= 0.")
        return iv

    rpm = _to_nonneg_int(requests_per_minute_limit, "requests_per_minute_limit")
    if isinstance(rpm, dict) and "error" in rpm:
        return rpm
    rpd = _to_nonneg_int(requests_per_day_limit, "requests_per_day_limit")
    if isinstance(rpd, dict) and "error" in rpd:
        return rpd
    mcl = _to_nonneg_int(monthly_credit_limit, "monthly_credit_limit")
    if isinstance(mcl, dict) and "error" in mcl:
        return mcl

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked.")

    # Authenticate explicit credential
    keys = _load("api_keys.json")
    presented = api_key.strip()
    presented_prefix = presented[:8]
    presented_hash = hashlib.sha256(presented.encode("utf-8")).hexdigest()

    manager = None
    for k in keys:
        if k.get("key_hash") == presented_hash or k.get("key_prefix") == presented_prefix or k.get("id") == presented:
            manager = k
            break
    if manager is None:
        return _err("UNAUTHORIZED", "Invalid api_key credential for key management.")

    if manager.get("status") != "active":
        duration_ms = int((_time.time() - t0) * 1000)
        _log(manager.get("id"), "updateApiKey", req_params, None, False, None, 0, duration_ms, "unauthorized", "API key not active")
        return _err("UNAUTHORIZED", "API key is not active.")

    credits_needed = 1
    consume_err = _enforce_and_consume(keys, manager, credits_needed)
    if consume_err:
        duration_ms = int((_time.time() - t0) * 1000)
        _log(manager["id"], "updateApiKey", req_params, None, False, None, 0, duration_ms, consume_err["error"]["code"].lower(), consume_err["error"]["message"][:240])
        return consume_err

    # Locate target key
    target = None
    for k in keys:
        if k.get("id") == id:
            target = k
            break
    if target is None:
        duration_ms = int((_time.time() - t0) * 1000)
        _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "not_found", "API key not found")
        return _err("NOT_FOUND", "API key not found.")

    # Apply updates with lifecycle transition rules
    transitions = {
        "active": {"suspended", "revoked"},
        "suspended": {"active", "revoked"},
        "revoked": set()
    }
    if status is not None:
        cur = target.get("status")
        if cur not in transitions:
            duration_ms = int((_time.time() - t0) * 1000)
            _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "validation_error", "Stored status invalid")
            return _err("VALIDATION_ERROR", "Stored key status is invalid.")
        if status != cur:
            if status not in transitions[cur]:
                duration_ms = int((_time.time() - t0) * 1000)
                _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "invalid_transition", "Illegal status transition")
                return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}")
            target["status"] = status

    if label is not None:
        # conflict check (global, since no account scope)
        for k in keys:
            if k.get("id") != target.get("id") and (k.get("label") or "").strip().lower() == label.strip().lower():
                duration_ms = int((_time.time() - t0) * 1000)
                _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "conflict", "label collision")
                return _err("CONFLICT", "label collides with an existing key.")
        target["label"] = label.strip()

    if plan_store is not None:
        # api_keys schema enum doesn't include "basic", store mapped value
        if plan_store not in ("free", "pro", "enterprise"):
            duration_ms = int((_time.time() - t0) * 1000)
            _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "validation_error", "plan not allowed by storage enum")
            return _err("VALIDATION_ERROR", "plan is not allowed.")
        target["plan"] = plan_store

    if rpm is not None:
        target["requests_per_minute_limit"] = int(rpm)
    if rpd is not None:
        target["requests_per_day_limit"] = int(rpd)
    if mcl is not None:
        target["monthly_credit_limit"] = int(mcl)

    # Ensure counters non-negative
    for fld in ("requests_today", "requests_this_minute", "credits_month_to_date"):
        v = target.get(fld)
        if not isinstance(v, int) or v < 0:
            duration_ms = int((_time.time() - t0) * 1000)
            _log(manager["id"], "updateApiKey", req_params, None, False, None, credits_needed, duration_ms, "validation_error", f"{fld} invalid")
            return _err("VALIDATION_ERROR", f"Stored {fld} invalid.")

    target["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    resp = {
        "status": {
            "timestamp": _iso(now),
            "error_code": 0,
            "error_message": None,
            "elapsed": int((_time.time() - t0) * 1000),
            "credit_count": credits_needed
        },
        "data": target
    }

    duration_ms = int((_time.time() - t0) * 1000)
    _log(manager["id"], "updateApiKey", req_params, None, False, 200, credits_needed, duration_ms, None, None)
    return resp

def requestLogs(api_key, start=None, limit=None, api_key_id=None, tool_name=None, cache_hit=None, time_start=None, time_end=None, sort_dir=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        # support trailing Z
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.date().isoformat()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _get_key_row(raw_key, api_keys_rows):
        if not isinstance(raw_key, str) or not raw_key:
            return None
        # Authenticate by matching client-visible value or id.
        # Store has key_prefix; treat raw key matching prefix (or exact prefix) as acceptable.
        # Also allow passing api_keys.id.
        candidates = []
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == raw_key:
                candidates.append(r)
                continue
            pref = r.get("key_prefix")
            if isinstance(pref, str) and pref:
                if raw_key == pref or raw_key.startswith(pref):
                    candidates.append(r)
        # Prefer active keys when multiple match
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0] if candidates else None

    def _log_request(logs, api_key_id_val, tool, params, cache_key=None, cache_hit_val=False,
                     upstream_http_status=None, credits_charged=0, duration_ms=0,
                     error_code=None, error_message=None):
        now = _now_utc()
        rid = f"rlog_{uuid.uuid4().hex}"
        rec = {
            "id": rid,
            "api_key_id": api_key_id_val,
            "tool_name": tool,
            "request_params": params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit_val),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged) if isinstance(credits_charged, int) and credits_charged >= 0 else 0,
            "duration_ms": int(duration_ms) if isinstance(duration_ms, int) and duration_ms >= 0 else 0,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else None),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(rec)
        return rid

    # Validate inputs (schema additionalProperties=false enforced by signature)
    if api_key is None or not isinstance(api_key, str) or not api_key:
        # No key -> cannot log
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    if start is None:
        start = 1
    if limit is None:
        limit = 100
    if not (isinstance(start, (int, float)) and int(start) == start and int(start) >= 1):
        return _err("VALIDATION_ERROR", "start must be an integer >= 1.")
    if not (isinstance(limit, (int, float)) and int(limit) == limit and 1 <= int(limit) <= 5000):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 5000.")
    start = int(start)
    limit = int(limit)

    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided.")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided.")
    if cache_hit is not None and not isinstance(cache_hit, bool):
        return _err("VALIDATION_ERROR", "cache_hit must be a boolean when provided.")
    if sort_dir is None:
        sort_dir = "desc"
    if sort_dir not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_dir must be one of: asc, desc.")

    ts = _parse_iso(time_start)
    if time_start is not None and ts is None:
        return _err("VALIDATION_ERROR", "time_start must be an ISO-8601 timestamp.")
    te = _parse_iso(time_end)
    if time_end is not None and te is None:
        return _err("VALIDATION_ERROR", "time_end must be an ISO-8601 timestamp.")
    if ts and te and ts > te:
        return _err("VALIDATION_ERROR", "time_start must be <= time_end.")

    # Load store
    api_keys_rows = _load("api_keys.json")
    logs = _load("request_logs.json")

    key_row = _get_key_row(api_key, api_keys_rows)
    if not key_row:
        # Cannot log without api_key_id
        return _err("UNAUTHORIZED", "Invalid api_key.")

    # Enforce key status active (requests must be rejected otherwise) but still log the attempt
    now = _now_utc()

    # Reset rolling windows if needed
    last = _parse_iso(key_row.get("last_request_at")) if key_row.get("last_request_at") else None
    if last is None:
        last = now
    # minute reset
    if _minute_bucket(last) != _minute_bucket(now):
        key_row["requests_this_minute"] = 0
    # day reset
    if _day_bucket(last) != _day_bucket(now):
        key_row["requests_today"] = 0
    # month reset
    if _month_bucket(last) != _month_bucket(now):
        key_row["credits_month_to_date"] = 0

    # Prepare validated params for logging (only allowed properties)
    params_for_log = {
        "api_key": api_key,
        "start": start,
        "limit": limit,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "cache_hit": cache_hit,
        "time_start": time_start,
        "time_end": time_end,
        "sort_dir": sort_dir,
    }

    # Authorization / entitlement:
    # - free/pro keys may only view their own logs.
    # - enterprise keys may filter any api_key_id.
    requested_key_id = api_key_id if api_key_id is not None else key_row.get("id")
    if requested_key_id != key_row.get("id") and key_row.get("plan") != "enterprise":
        # Log and return forbidden (tool description mentions FORBIDDEN; map to UNAUTHORIZED codes list -> UNAUTHORIZED)
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(
            logs, key_row.get("id"), "requestLogs", params_for_log,
            cache_key=None, cache_hit_val=False, upstream_http_status=None,
            credits_charged=0, duration_ms=duration_ms,
            error_code="forbidden", error_message="Not entitled to view other api_key_id logs."
        )
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("UNAUTHORIZED", "Not entitled to view logs for the requested api_key_id.")

    # Rate limit / daily / credit (this endpoint costs 0 credits but counts as request)
    if key_row.get("status") != "active":
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(
            logs, key_row.get("id"), "requestLogs", params_for_log,
            cache_key=None, cache_hit_val=False, upstream_http_status=None,
            credits_charged=0, duration_ms=duration_ms,
            error_code="key_inactive", error_message="API key is not active."
        )
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    rpm = key_row.get("requests_per_minute_limit", 0)
    rpd = key_row.get("requests_per_day_limit", 0)
    if isinstance(rpm, int) and rpm > 0 and int(key_row.get("requests_this_minute", 0)) >= rpm:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(
            logs, key_row.get("id"), "requestLogs", params_for_log,
            error_code="rate_limited", error_message="requests_per_minute_limit exceeded.",
            duration_ms=duration_ms
        )
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute).")
    if isinstance(rpd, int) and rpd > 0 and int(key_row.get("requests_today", 0)) >= rpd:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(
            logs, key_row.get("id"), "requestLogs", params_for_log,
            error_code="quota_exceeded", error_message="requests_per_day_limit exceeded.",
            duration_ms=duration_ms
        )
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Consume request counters
    key_row["requests_this_minute"] = int(key_row.get("requests_this_minute", 0)) + 1
    key_row["requests_today"] = int(key_row.get("requests_today", 0)) + 1
    key_row["last_request_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    # Filter logs
    def _created_at_dt(r):
        d = _parse_iso(r.get("created_at")) if isinstance(r, dict) else None
        return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != requested_key_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if cache_hit is not None and bool(r.get("cache_hit")) != cache_hit:
            continue
        cad = _created_at_dt(r)
        if ts and cad < ts:
            continue
        if te and cad > te:
            continue
        filtered.append(r)

    reverse = True if sort_dir == "desc" else False
    filtered.sort(key=_created_at_dt, reverse=reverse)

    total = len(filtered)
    offset = start - 1
    page = filtered[offset: offset + limit] if offset < total else []
    has_more = (offset + limit) < total
    next_cursor = (start + limit) if has_more else None

    duration_ms = int((time.time() - _t0) * 1000)
    _log_request(
        logs, key_row.get("id"), "requestLogs", params_for_log,
        cache_key=None, cache_hit_val=False, upstream_http_status=None,
        credits_charged=0, duration_ms=duration_ms,
        error_code=None, error_message=None
    )

    _save("request_logs.json", logs)
    _save("api_keys.json", api_keys_rows)

    return {
        "data": page,
        "metadata": {
            "start": start,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_dir": sort_dir,
        }
    }

def cachedResponse(api_key, tool_name, params_fingerprint, include_body=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else d.get("rows", []) if isinstance(d, dict) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    this_tool = "cachedResponse"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
        elif isinstance(s, str) and s.strip():
            v = s.strip()
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        val = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[val % 32])
            val //= 32
        chars = list(reversed(chars))
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return f"{prefix}_{''.join(chars)}"

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        return dt.date()

    def _month_bucket(dt):
        return (dt.year, dt.month)

    def _append_log(api_key_id_used, request_params, cache_key, cache_hit, upstream_http_status, credits_charged, duration_ms, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("cmc_req"),
            "api_key_id": api_key_id_used,
            "tool_name": this_tool,
            "request_params": request_params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(max(0, int(credits_charged))),
            "duration_ms": int(max(0, int(duration_ms))),
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else error_message),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _enforce_and_increment(api_key_row, credits_to_charge):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "Invalid api_key")
        row = keys[idx]
        if row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active")

        last_dt = _parse_iso(row.get("last_request_at"))
        if last_dt is None:
            last_dt = now - datetime.timedelta(days=3650)

        if _minute_bucket(last_dt) != _minute_bucket(now):
            row["requests_this_minute"] = 0
        if _day_bucket(last_dt) != _day_bucket(now):
            row["requests_today"] = 0
        if _month_bucket(last_dt) != _month_bucket(now):
            row["credits_month_to_date"] = 0

        rpm = row.get("requests_per_minute_limit", 0) or 0
        rpd = row.get("requests_per_day_limit", 0) or 0
        mcl = row.get("monthly_credit_limit", 0) or 0
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        try:
            rpd = int(rpd)
        except Exception:
            rpd = 0
        try:
            mcl = int(mcl)
        except Exception:
            mcl = 0

        if rpm > 0 and int(row.get("requests_this_minute", 0) or 0) >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded: requests_per_minute_limit", limit=rpm)
        if rpd > 0 and int(row.get("requests_today", 0) or 0) >= rpd:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded: requests_per_day_limit", limit=rpd)
        if mcl > 0 and (int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)) > mcl:
            return _err("QUOTA_EXCEEDED", "Monthly credit quota exceeded: monthly_credit_limit", limit=mcl)

        row["requests_this_minute"] = int(row.get("requests_this_minute", 0) or 0) + 1
        row["requests_today"] = int(row.get("requests_today", 0) or 0) + 1
        row["credits_month_to_date"] = int(row.get("credits_month_to_date", 0) or 0) + int(credits_to_charge)
        row["last_request_at"] = _iso(now)
        row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    # validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(tool_name, str) or not tool_name.strip():
        return _err("VALIDATION_ERROR", "tool_name is required and must be a non-empty string")
    if not isinstance(params_fingerprint, str) or not params_fingerprint.strip():
        return _err("VALIDATION_ERROR", "params_fingerprint is required and must be a non-empty string")
    if include_body is not None and not isinstance(include_body, bool):
        return _err("VALIDATION_ERROR", "include_body must be a boolean when provided")

    request_params = {
        "api_key": api_key.strip(),
        "tool_name": tool_name.strip(),
        "params_fingerprint": params_fingerprint.strip(),
    }
    if include_body is not None:
        request_params["include_body"] = include_body

    # authenticate api_key param via id or key_prefix (client-visible), not key_hash
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    presented = api_key.strip()
    presented_prefix = presented[:8]
    caller = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == presented or k.get("key_prefix") == presented or k.get("key_prefix") == presented_prefix:
            caller = k
            break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # This tool is allowed for any active key (fix audit: do not forbid)
    qerr = _enforce_and_increment(caller, 1)
    if qerr:
        _append_log(caller.get("id"), request_params, None, False, None, 0, int((time.time() - t0) * 1000), error_code=qerr["error"]["code"].lower(), error_message=qerr["error"]["message"])
        return qerr

    cache_key = f"{tool_name.strip()}:{params_fingerprint.strip()}"

    rows = _load("cached_responses.json")
    if not isinstance(rows, list):
        rows = []
    hit = None
    for r in rows:
        if isinstance(r, dict) and r.get("tool_name") == tool_name.strip() and r.get("params_fingerprint") == params_fingerprint.strip():
            hit = r
            break

    if hit is None:
        _append_log(caller.get("id"), request_params, cache_key, False, 404, 0, int((time.time() - t0) * 1000), error_code="not_found", error_message="Cache entry not found")
        return _err("NOT_FOUND", "Cache entry not found")

    # include validity info; cache_hit semantics here are not "served from cache", but this endpoint is itself a cache read
    body = {
        "id": hit.get("id"),
        "tool_name": hit.get("tool_name"),
        "params_fingerprint": hit.get("params_fingerprint"),
        "request_params": hit.get("request_params"),
        "http_status": hit.get("http_status"),
        "etag": hit.get("etag"),
        "expires_at": hit.get("expires_at"),
        "status": hit.get("status"),
        "created_at": hit.get("created_at"),
        "updated_at": hit.get("updated_at"),
    }
    if include_body:
        body["response_body"] = hit.get("response_body")

    response = {"status": {"timestamp": _iso(now), "error_code": 0, "error_message": None}, "data": body}

    _append_log(caller.get("id"), request_params, cache_key, True, 200, 1, int((time.time() - t0) * 1000))
    return response

def refreshCache(api_key, target, scope, entity_type=None, id=None, slug=None, symbol=None, tool_name=None, params_fingerprint=None, force=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0469000" if __import__("os").path.isdir("./environment_mix/0469000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat()
        return None

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _minute_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.date().isoformat()

    def _month_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _get_key_row(raw_key, api_keys_rows):
        if not isinstance(raw_key, str) or not raw_key:
            return None
        candidates = []
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == raw_key:
                candidates.append(r)
                continue
            pref = r.get("key_prefix")
            if isinstance(pref, str) and pref:
                if raw_key == pref or raw_key.startswith(pref):
                    candidates.append(r)
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0] if candidates else None

    def _log_request(logs, api_key_id_val, params, cache_key=None, cache_hit_val=False,
                     upstream_http_status=None, credits_charged=0, duration_ms=0,
                     error_code=None, error_message=None):
        now = _now_utc()
        rid = f"rlog_{uuid.uuid4().hex}"
        rec = {
            "id": rid,
            "api_key_id": api_key_id_val,
            "tool_name": "refreshCache",
            "request_params": params,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit_val),
            "upstream_http_status": upstream_http_status,
            "credits_charged": int(credits_charged) if isinstance(credits_charged, int) and credits_charged >= 0 else 0,
            "duration_ms": int(duration_ms) if isinstance(duration_ms, int) and duration_ms >= 0 else 0,
            "error_code": error_code,
            "error_message": (error_message[:240] if isinstance(error_message, str) else None),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(rec)
        return rid

    # Validate basic
    if not isinstance(api_key, str) or not api_key:
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if target not in ("asset_directory", "categories_and_memberships", "market_data", "cached_responses"):
        return _err("VALIDATION_ERROR", "Unsupported target.")
    if scope not in ("all", "by_id", "by_slug", "by_symbol", "by_fingerprint"):
        return _err("VALIDATION_ERROR", "Unsupported scope.")
    if force is None:
        force = False
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean when provided.")
    if entity_type is not None and entity_type not in ("cryptocurrency", "fiat", "exchange", "dex", "dex_network", "dex_pair"):
        return _err("VALIDATION_ERROR", "entity_type must be one of the allowed enums when provided.")
    for nm, val in (("id", id), ("slug", slug), ("symbol", symbol), ("tool_name", tool_name), ("params_fingerprint", params_fingerprint)):
        if val is not None and (not isinstance(val, str) or not val.strip()):
            return _err("VALIDATION_ERROR", f"{nm} must be a non-empty string when provided.")

    # Scope/target requirements
    if scope == "by_id" and not id:
        return _err("VALIDATION_ERROR", "id is required when scope=by_id.")
    if scope == "by_slug" and not slug:
        return _err("VALIDATION_ERROR", "slug is required when scope=by_slug.")
    if scope == "by_symbol" and not symbol:
        return _err("VALIDATION_ERROR", "symbol is required when scope=by_symbol.")
    if scope == "by_fingerprint" and not params_fingerprint:
        return _err("VALIDATION_ERROR", "params_fingerprint is required when scope=by_fingerprint.")
    if target == "cached_responses":
        if not tool_name:
            return _err("VALIDATION_ERROR", "tool_name is required when target=cached_responses.")
        if scope not in ("all", "by_fingerprint"):
            return _err("VALIDATION_ERROR", "For target=cached_responses, scope must be all or by_fingerprint.")
    if target == "asset_directory":
        if scope in ("by_symbol",) and not symbol:
            return _err("VALIDATION_ERROR", "symbol is required for asset_directory when scope=by_symbol.")
        # entity_type optional; but for dex_pair in asset_directory doesn't exist (pairs are market_data); allow for validation parity
    if target == "categories_and_memberships":
        if scope in ("by_symbol", "by_fingerprint"):
            return _err("VALIDATION_ERROR", "Unsupported scope for categories_and_memberships.")
    if target == "market_data":
        if scope == "by_symbol" and not symbol:
            return _err("VALIDATION_ERROR", "symbol is required for market_data when scope=by_symbol.")
        if scope == "by_fingerprint":
            return _err("VALIDATION_ERROR", "Unsupported scope for market_data.")

    api_keys_rows = _load("api_keys.json")
    logs = _load("request_logs.json")

    key_row = _get_key_row(api_key, api_keys_rows)
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid api_key.")

    now = _now_utc()
    last = _parse_iso(key_row.get("last_request_at")) if key_row.get("last_request_at") else None
    if last is None:
        last = now
    if _minute_bucket(last) != _minute_bucket(now):
        key_row["requests_this_minute"] = 0
    if _day_bucket(last) != _day_bucket(now):
        key_row["requests_today"] = 0
    if _month_bucket(last) != _month_bucket(now):
        key_row["credits_month_to_date"] = 0

    params_for_log = {
        "api_key": api_key,
        "target": target,
        "scope": scope,
        "entity_type": entity_type,
        "id": id,
        "slug": slug,
        "symbol": symbol,
        "tool_name": tool_name,
        "params_fingerprint": params_fingerprint,
        "force": force,
    }

    # Active key required
    if key_row.get("status") != "active":
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="key_inactive", error_message="API key is not active.")
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("UNAUTHORIZED", "API key is not active.", status=key_row.get("status"))

    # Entitlement: only enterprise can trigger refresh
    if key_row.get("plan") != "enterprise":
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="forbidden", error_message="Not entitled to trigger refresh.")
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("UNAUTHORIZED", "Not entitled to trigger refresh.")

    # Rate / daily quotas still apply
    rpm = key_row.get("requests_per_minute_limit", 0)
    rpd = key_row.get("requests_per_day_limit", 0)
    if isinstance(rpm, int) and rpm > 0 and int(key_row.get("requests_this_minute", 0)) >= rpm:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="rate_limited", error_message="requests_per_minute_limit exceeded.")
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("RATE_LIMIT", "Rate limit exceeded (per-minute).")
    if isinstance(rpd, int) and rpd > 0 and int(key_row.get("requests_today", 0)) >= rpd:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="quota_exceeded", error_message="requests_per_day_limit exceeded.")
        _save("request_logs.json", logs)
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Refresh operation quota: enforce a small daily refresh quota based on plan
    # (business rule mentions refresh limits but schema has no dedicated counter; enforce via request_logs tool_name=refreshCache per UTC day)
    refresh_limits = {"free": 0, "pro": 0, "enterprise": 500}
    refresh_daily_limit = refresh_limits.get(key_row.get("plan"), 0)

    # Count refreshCache calls today for this key
    today = now.date()
    refresh_count_today = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        if r.get("tool_name") != "refreshCache":
            continue
        cad = _parse_iso(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if cad and cad.date() == today and not r.get("error_code"):
            refresh_count_today += 1

    if refresh_daily_limit > 0 and refresh_count_today >= refresh_daily_limit:
        duration_ms = int((time.time() - _t0) * 1000)
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="refresh_quota_exceeded", error_message="Refresh daily quota exceeded.")
        _save("request_logs.json", logs)
        key_row["requests_this_minute"] = int(key_row.get("requests_this_minute", 0)) + 1
        key_row["requests_today"] = int(key_row.get("requests_today", 0)) + 1
        key_row["last_request_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        _save("api_keys.json", api_keys_rows)
        return _err("QUOTA_EXCEEDED", "Refresh quota exceeded.")

    # Consume request counters
    key_row["requests_this_minute"] = int(key_row.get("requests_this_minute", 0)) + 1
    key_row["requests_today"] = int(key_row.get("requests_today", 0)) + 1
    key_row["last_request_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    # Apply "scheduling" effect: mark affected rows as stale/expired unless force implies always.
    affected = 0
    detail = {"marked": []}

    def _mark_asset_directory():
        nonlocal affected
        rows = _load("asset_directory.json")
        changed = False
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") == "deleted":
                continue
            if entity_type and r.get("entity_type") != entity_type:
                continue
            ok = False
            if scope == "all":
                ok = True
            elif scope == "by_id":
                ok = (r.get("upstream_id") == id or r.get("id") == id)
            elif scope == "by_slug":
                ok = (r.get("slug") == slug)
            elif scope == "by_symbol":
                ok = (r.get("symbol") == symbol)
            elif scope == "by_fingerprint":
                ok = False
            if not ok:
                continue
            if (not force) and r.get("status") == "stale":
                continue
            if r.get("status") == "current":
                r["status"] = "stale"
                r["updated_at"] = _iso(now)
                affected += 1
                changed = True
        if changed:
            _save("asset_directory.json", rows)

    def _mark_categories():
        nonlocal affected
        rows = _load("categories_and_memberships.json")
        changed = False
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") == "deleted":
                continue
            ok = False
            if scope == "all":
                ok = True
            elif scope == "by_id":
                ok = (r.get("upstream_id") == id or r.get("id") == id)
            elif scope == "by_slug":
                ok = (r.get("slug") == slug)
            else:
                ok = False
            if not ok:
                continue
            if (not force) and r.get("status") == "stale":
                continue
            if r.get("status") == "current":
                r["status"] = "stale"
                r["updated_at"] = _iso(now)
                affected += 1
                changed = True
        if changed:
            _save("categories_and_memberships.json", rows)

    def _mark_market_data():
        nonlocal affected
        rows = _load("market_data.json")
        assets = _load("asset_directory.json")
        # Build symbol->asset ids for cryptocurrency/fiat
        sym_to_asset_ids = {}
        for a in assets:
            if not isinstance(a, dict):
                continue
            sym = a.get("symbol")
            if isinstance(sym, str) and sym:
                sym_to_asset_ids.setdefault(sym, set()).add(a.get("id"))
        changed = False
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") == "deleted":
                continue
            ok = False
            if scope == "all":
                ok = True
            elif scope == "by_id":
                ok = (r.get("id") == id or r.get("primary_asset_id") == id or r.get("secondary_asset_id") == id)
            elif scope == "by_slug":
                ok = False
            elif scope == "by_symbol":
                ids = sym_to_asset_ids.get(symbol, set())
                ok = (r.get("primary_asset_id") in ids or r.get("secondary_asset_id") in ids)
            else:
                ok = False
            if not ok:
                continue
            if (not force) and r.get("status") == "stale":
                continue
            if r.get("status") == "fresh":
                r["status"] = "stale"
                r["updated_at"] = _iso(now)
                affected += 1
                changed = True
        if changed:
            _save("market_data.json", rows)

    def _mark_cached_responses():
        nonlocal affected
        rows = _load("cached_responses.json")
        changed = False
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != tool_name:
                continue
            if r.get("status") == "purged":
                continue
            ok = False
            if scope == "all":
                ok = True
            elif scope == "by_fingerprint":
                ok = (r.get("params_fingerprint") == params_fingerprint)
            else:
                ok = False
            if not ok:
                continue
            # Refresh scheduling: expire valid entries so next call repopulates upstream/cache
            if (not force) and r.get("status") == "expired":
                continue
            if r.get("status") == "valid":
                r["status"] = "expired"
                r["updated_at"] = _iso(now)
                affected += 1
                changed = True
        if changed:
            _save("cached_responses.json", rows)

    # Perform mutation based on target
    if target == "asset_directory":
        _mark_asset_directory()
    elif target == "categories_and_memberships":
        _mark_categories()
    elif target == "market_data":
        _mark_market_data()
    elif target == "cached_responses":
        _mark_cached_responses()

    duration_ms = int((time.time() - _t0) * 1000)

    if affected == 0:
        _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                     error_code="not_found", error_message="No matching records to refresh.")
        _save("request_logs.json", logs)
        _save("api_keys.json", api_keys_rows)
        return _err("NOT_FOUND", "No matching records found to refresh.")

    _log_request(logs, key_row.get("id"), params_for_log, duration_ms=duration_ms,
                 error_code=None, error_message=None)

    _save("request_logs.json", logs)
    _save("api_keys.json", api_keys_rows)

    job_id = f"rjob_{uuid.uuid4().hex}"
    return {
        "data": {
            "job_id": job_id,
            "status": "scheduled",
            "target": target,
            "scope": scope,
            "affected_records": affected,
            "scheduled_at": _iso(now),
            "force": force,
        }
    }
